// The desk: in-tray on the left, the current document in the middle, the wall on the right.

import { ORDINANCES } from "../sim/ordinances";
import { DEPT_IDS, type Citizen, type DeptId, type DocKind, type Document, type TownState } from "../sim/types";
import { fullName } from "../sim/util";
import { h, paragraphs } from "./dom";
import { townMapSvg } from "./map";
import { skySvg } from "./sky";

export interface DeskCallbacks {
  select(id: number | null): void;
  stamp(docId: number, option: string): void;
  bulletin(id: string): void;
  reassign(citizenId: number, dept: DeptId): void;
  endDay(): void;
}

const FORM: Record<DocKind, string> = {
  permit: "Form P-11",
  resignation: "Form HR-3",
  complaint: "Form C-2",
  ordinance: "Council Proposal",
  budget: "Form F-7",
  federal: "Federal Circular",
  confession: "Statement",
  question: "Inquiry",
  petition: "Petition",
  memo: "Memorandum",
  exploit: "Application",
  staffing: "Form HR-9",
};

const OPTION_KEYS = ["1", "2", "3", "4"];

export function renderInTray(state: TownState, selected: number | null, cb: DeskCallbacks): HTMLElement {
  const pending = state.inTray.filter((d) => d.status === "pending" && d.chosen !== "defer");
  const done = state.inTray.filter((d) => d.status !== "pending" || d.chosen === "defer");
  const item = (d: Document) =>
    h(
      "button",
      {
        class: `tray-item ${d.id === selected ? "selected" : ""} ${d.status !== "pending" ? "done" : ""} ${d.chosen === "defer" ? "deferred" : ""} ${d.age > 0 ? "aged" : ""}`,
        onclick: () => cb.select(d.id),
        type: "button",
      },
      h("span", { class: "tray-kind" }, FORM[d.kind]),
      h("span", { class: "tray-title" }, d.title),
      h("span", { class: "tray-from" }, d.senderLabel),
      d.status !== "pending" ? h("span", { class: "tray-stamp" }, labelFor(d)) : d.chosen === "defer" ? h("span", { class: "tray-stamp muted" }, "Deferred") : null,
    );
  return h(
    "aside",
    { class: "tray" },
    h(
      "div",
      { class: "tray-head" },
      h("button", { class: "link", type: "button", onclick: () => cb.select(null) }, "Morning briefing"),
      h("span", { class: "stamps" }, `${state.stampsLeft} of ${state.stampsPerDay} stamps`),
    ),
    h("h2", {}, "In-tray"),
    pending.length ? pending.map(item) : h("p", { class: "empty" }, done.length ? "Everything has been seen to." : "Nothing in the tray."),
    done.length ? h("h2", { class: "out" }, "Out-tray") : null,
    done.map(item),
    h(
      "section",
      { class: "townmap" },
      h("h2", { class: "out" }, "The town"),
      h("p", { class: "map-note" }, "Planning Department diagram. Hover a household for a name."),
      h("div", { class: "map", html: townMapSvg(state) }),
    ),
  );
}

function labelFor(d: Document): string {
  const opt = d.options.find((o) => o.id === d.chosen);
  if (d.status === "lapsed") return "Lapsed";
  return opt ? stampWord(opt.label) : d.chosen ?? "";
}

function stampWord(label: string): string {
  const map: Record<string, string> = {
    Approve: "Approved",
    Deny: "Denied",
    Sign: "Signed",
    Decline: "Declined",
    Accept: "Accepted",
    File: "Filed",
    Prosecute: "Prosecuted",
    Pardon: "Pardoned",
    Negotiate: "Settled",
    Refuse: "Refused",
    Dismiss: "Dismissed",
    Defer: "Deferred",
  };
  return map[label] ?? label;
}

export function renderBriefing(state: TownState): HTMLElement {
  const staff = state.citizens.filter((c) => c.dept && c.present && c.working).length;
  const pending = state.inTray.filter((d) => d.status === "pending").length;
  const lines: string[] = [];
  if (state.day === 1) lines.push("You are the Deputy Clerk. As of this morning you are also everything else.");
  if (!state.office.held) lines.push(`You no longer hold the office. It was taken on Day ${state.office.lostDay} by ${state.office.lostTo}. Documents still arrive. You may read them.`);
  for (const e of state.events) lines.push(e);
  if (lines.length === 0) lines.push("Nothing to report overnight, which is itself reported.");
  lines.push(`Staff reporting for duty: ${staff} of ${state.kpis.headcountStart}.`);
  lines.push(`Documents in the tray: ${pending}. Stamps available: ${state.stampsPerDay}.`);
  if (state.day === 30) lines.push("One document today. Then the lights.");
  return h(
    "article",
    { class: "doc memo briefing" },
    h("header", { class: "doc-head" }, h("span", { class: "doc-form" }, "Memorandum"), h("span", { class: "doc-day" }, `Day ${state.day} of 30`)),
    h("h1", {}, "Morning briefing"),
    h("p", { class: "doc-from" }, `To: Acting Town Manager. From: the desk.`),
    h("ul", { class: "briefing-lines" }, lines.map((l) => h("li", {}, l))),
    h("p", { class: "hint" }, "Select a document from the in-tray. Keys 1 to 4 stamp the options; E ends the day."),
  );
}

export function renderDocument(state: TownState, doc: Document, cb: DeskCallbacks): HTMLElement {
  const resolved = doc.status !== "pending";
  const deferred = doc.chosen === "defer" && !resolved;
  const canStamp = !resolved && !deferred && state.stampsLeft > 0 && state.office.held;
  const stampLabel = resolved ? labelFor(doc).toUpperCase() : deferred ? "DEFERRED" : null;
  return h(
    "article",
    { class: `doc ${doc.kind === "memo" || doc.kind === "federal" ? "memo" : ""} ${resolved ? "resolved" : ""}` },
    h(
      "header",
      { class: "doc-head" },
      h("span", { class: "doc-form" }, FORM[doc.kind]),
      h("span", { class: "doc-day" }, `Received Day ${doc.day}${doc.age > 0 ? `, deferred ${doc.age}` : ""}`),
    ),
    h("h1", {}, doc.title),
    h("p", { class: "doc-from" }, `From: ${doc.senderLabel}`),
    h("div", { class: "doc-body" }, paragraphs(doc.body)),
    stampLabel ? h("div", { class: `stamp-mark ${deferred || doc.status === "lapsed" ? "grey" : ""}` }, stampLabel) : null,
    resolved && doc.outcome ? h("div", { class: "disposition" }, h("h3", {}, "Disposition"), paragraphs(doc.outcome)) : null,
    !resolved
      ? h(
          "div",
          { class: "stamps-row" },
          doc.options.map((o, i) =>
            h(
              "button",
              {
                class: `stamp-btn ${o.id === "deny" || o.id === "refuse" || o.id === "decline" ? "red" : ""} ${o.id === "defer" ? "grey" : ""}`,
                type: "button",
                disabled: !canStamp,
                onclick: () => cb.stamp(doc.id, o.id),
                title: `Key ${OPTION_KEYS[i] ?? ""}`,
              },
              h("span", { class: "key" }, OPTION_KEYS[i] ?? ""),
              o.label,
            ),
          ),
          !state.office.held ? h("p", { class: "hint" }, "Not yours to stamp any more.") : state.stampsLeft === 0 ? h("p", { class: "hint" }, deferred ? "Deferred until tomorrow." : "No stamps left today. It will resolve itself.") : deferred ? h("p", { class: "hint" }, "Deferred until tomorrow.") : null,
        )
      : null,
  );
}

function meter(label: string, value: number, note?: string): HTMLElement {
  const v = Math.round(Math.max(0, Math.min(1, value)) * 100);
  return h(
    "div",
    { class: "meter" },
    h("div", { class: "meter-label" }, h("span", {}, label), h("span", { class: "meter-value" }, note ?? `${v}`)),
    h("div", { class: "meter-bar" }, h("div", { class: "meter-fill", style: `width:${v}%` })),
  );
}

function donorFor(state: TownState, to: DeptId): Citizen | null {
  let best: { c: Citizen; strength: number } | null = null;
  for (const dept of state.departments) {
    if (dept.id === to) continue;
    const strength = state.services[dept.id];
    if (strength < 0.5) continue;
    const c = state.citizens.find((x) => x.dept === dept.id && x.present && x.working && x.role === null);
    if (c && (!best || strength > best.strength)) best = { c, strength };
  }
  return best?.c ?? null;
}

export function renderWall(state: TownState, cb: DeskCallbacks): HTMLElement {
  const staff = state.citizens.filter((c) => c.dept && c.present && c.working).length;
  const active = state.ordinances.filter((o) => o.active);
  const bulletinId = state.bulletinToday ?? "silence";
  return h(
    "aside",
    { class: "wall" },
    h("div", { class: "window", html: skySvg(state.day) }),
    h(
      "section",
      { class: "kpi" },
      h("h2", {}, "Key performance indicators"),
      h("p", { class: "tiny" }, "Confidential. Do not circulate. Circulated."),
      meter("Public confidence", state.trust),
      meter("Compliance index", state.order),
      meter("Citizen satisfaction", state.morale),
      meter("Headcount", staff / Math.max(1, state.kpis.headcountStart), `${staff} / ${state.kpis.headcountStart}`),
      meter("Days remaining", (31 - state.day) / 30, `${31 - state.day}`),
    ),
    h(
      "section",
      { class: "depts" },
      h("h2", {}, "Departments"),
      state.departments.map((d) => {
        const n = state.citizens.filter((c) => c.dept === d.id && c.present && c.working).length;
        const strength = state.services[d.id];
        const donor = state.office.held ? donorFor(state, d.id) : null;
        return h(
          "div",
          { class: `dept ${strength < 0.5 ? "weak" : ""}` },
          h("span", { class: "dept-name" }, d.name),
          h("span", { class: "dept-n" }, `${n}/${d.required}`),
          h("div", { class: "meter-bar small" }, h("div", { class: "meter-fill", style: `width:${Math.min(100, Math.round(strength * 100))}%` })),
          h("button", { class: "mini", type: "button", disabled: !donor, title: donor ? `Move ${fullName(donor)} here` : "Nobody to spare", onclick: () => donor && cb.reassign(donor.id, d.id) }, "+1"),
        );
      }),
    ),
    h(
      "section",
      { class: "ordinances" },
      h("h2", {}, "Ordinances in force"),
      active.length
        ? h("ul", {}, active.map((o) => h("li", {}, h("span", {}, ORDINANCES[o.id].name), h("span", { class: "tiny" }, ` Day ${o.signedDay}${o.exploited ? ". Exceptions found." : ""}`))))
        : h("p", { class: "tiny" }, "None. The Charter applies, such as it is."),
    ),
    h(
      "section",
      { class: "bulletin" },
      h("h2", {}, "Today's bulletin"),
      state.office.held
        ? h(
            "div",
            { class: "options" },
            state.bulletinOptions.map((o) =>
              h(
                "label",
                { class: `option ${o.id === bulletinId ? "chosen" : ""}` },
                h("input", { type: "radio", name: "bulletin", value: o.id, checked: o.id === bulletinId, onchange: () => cb.bulletin(o.id) }),
                h("span", {}, o.text),
              ),
            ),
          )
        : h("p", { class: "tiny" }, "The bulletin is no longer yours to write."),
    ),
    h(
      "div",
      { class: "end-day" },
      h("button", { class: "big", type: "button", onclick: () => cb.endDay() }, state.day === 30 ? "Close of business" : "End the day"),
      h("p", { class: "tiny" }, `${state.stampsLeft} stamp${state.stampsLeft === 1 ? "" : "s"} unused. Unstamped documents resolve themselves.`),
    ),
  );
}

export { DEPT_IDS };
