// How citizens cope, and how coping spreads street by street.

import type { Rng } from "./rng";
import { COPING_STYLES, type Beliefs, type Citizen, type CopingStyle, type TownState } from "./types";
import { bell, clamp } from "./util";

export interface Modifiers {
  curfew: boolean;
  rationing: boolean;
  priceControls: boolean;
  schoolsClosed: boolean;
  barsOpen: boolean;
  optimism: boolean;
  legalizeAll: boolean;
  holiday: boolean;
  payrollFreeze: boolean;
  pensionRaided: boolean;
  welfareChecks: boolean;
  banHoarding: boolean;
}

export function styleIndex(s: CopingStyle): number {
  return COPING_STYLES.indexOf(s);
}

/** The month's shape: which ways of coping the calendar itself pushes on a given day. */
export function arcWeight(style: CopingStyle, day: number): number {
  switch (style) {
    case "denial":
      return Math.max(-0.25, 1 - day / 8);
    case "duty":
      return 0.5;
    case "hedonism":
      return 0.1 + 0.5 * bell(day, 18, 8);
    case "piety":
      return 0.1 + 0.5 * clamp(day / 20);
    case "rage":
      return 0.1 + 0.6 * bell(day, 10, 6);
    case "hoarding":
      return 0.7 * bell(day, 6, 4) - 0.15 * clamp((day - 10) / 10);
    case "flight":
      return 0.05 + 0.5 * bell(day, 5, 4);
    case "confession":
      return 0.25 * bell(day, 15, 10);
    case "bargaining":
      return 0.05 + 0.6 * bell(day, 9, 5);
    case "quiet":
      return 0.6 * clamp((day - 8) / 22);
  }
}

export function effectiveTrust(state: TownState, c: Citizen): number {
  return clamp(state.trust + c.trustOffset);
}

/** Fraction of present citizens on each street with each coping style. */
export function streetMix(state: TownState): number[][] {
  const mix = state.streets.map(() => COPING_STYLES.map(() => 0));
  const counts = state.streets.map(() => 0);
  for (const c of state.citizens) {
    if (!c.present) continue;
    const row = mix[c.street];
    if (!row) continue;
    const k = styleIndex(c.coping);
    row[k] = (row[k] ?? 0) + 1;
    counts[c.street] = (counts[c.street] ?? 0) + 1;
  }
  mix.forEach((row, i) => {
    const n = counts[i] ?? 0;
    if (n === 0) return;
    for (let k = 0; k < row.length; k++) row[k] = (row[k] ?? 0) / n;
  });
  return mix;
}

/** A one-off nudge to a street's contagion, decaying by half each day. Negative values dampen. */
export function pulse(state: TownState, street: number, style: CopingStyle, amount: number): void {
  const row = state.streetPulse[street];
  if (!row) return;
  const k = styleIndex(style);
  row[k] = (row[k] ?? 0) + amount;
}

export function pulseAll(state: TownState, style: CopingStyle, amount: number): void {
  for (let i = 0; i < state.streets.length; i++) pulse(state, i, style, amount);
}

/** Move the beliefs of a street (or the whole town) toward a value, scaled by how much they trust the source. */
export function spreadBelief(
  state: TownState,
  street: number | null,
  fact: keyof Beliefs,
  value: number,
  strength: number,
): void {
  for (const c of state.citizens) {
    if (!c.present) continue;
    if (street !== null && c.street !== street) continue;
    const w = strength * (0.4 + 0.6 * effectiveTrust(state, c));
    c.beliefs[fact] = clamp(c.beliefs[fact] + (value - c.beliefs[fact]) * w);
  }
}

export function meanBelief(state: TownState, fact: keyof Beliefs): number {
  let s = 0;
  let n = 0;
  for (const c of state.citizens) {
    if (!c.present) continue;
    s += c.beliefs[fact];
    n++;
  }
  return n ? s / n : 0;
}

export function pressures(
  state: TownState,
  c: Citizen,
  mix: number[][],
  mods: Modifiers,
): Record<CopingStyle, number> {
  const day = state.day;
  const row = mix[c.street] ?? [];
  const pulseRow = state.streetPulse[c.street] ?? [];
  const street = state.streets[c.street];
  const trust = effectiveTrust(state, c);
  const p = {} as Record<CopingStyle, number>;
  for (const s of COPING_STYLES) {
    const k = styleIndex(s);
    const contagion = Math.min(0.35, row[k] ?? 0) + Math.min(0.5, pulseRow[k] ?? 0);
    p[s] = c.prop[s] * (0.4 + arcWeight(s, day)) + contagion * (0.15 + 0.35 * c.traits.sociable);
  }
  if (street && !street.water) {
    p.rage += 0.3;
    p.hoarding += 0.2;
  }
  if (street && !street.power) {
    p.rage += 0.2;
    p.quiet += 0.05 * c.traits.anxious;
  }
  if (trust < 0.3) {
    p.rage += 0.2;
    p.flight += 0.1;
    p.duty -= 0.2;
  } else if (trust > 0.7) {
    p.duty += 0.2;
  }
  if (c.mood < -0.3) {
    p.quiet += 0.25 * c.traits.anxious;
    p.rage += 0.1;
  } else if (c.mood > 0.3) {
    p.hedonism += 0.1;
    p.quiet -= 0.1;
  }
  if (c.beliefs.real < 0.5) p.denial += 0.3;
  if (c.beliefs.miss > 0.5) {
    p.bargaining += 0.15;
    p.denial += 0.15;
  }
  if (c.age >= 60) {
    p.piety += 0.1;
    p.hedonism -= 0.1;
  } else if (c.age < 30) {
    p.hedonism += 0.1;
    p.flight += 0.05;
  }
  if (c.dept) p.duty += 0.15;
  if (mods.curfew) {
    p.duty += 0.1;
    p.rage += c.coping === "hedonism" ? 0.25 : 0.05;
  }
  if (mods.barsOpen) p.hedonism += 0.2;
  if (mods.rationing) p.hoarding += 0.15;
  if (mods.banHoarding) p.hoarding += 0.1;
  if (mods.holiday) {
    p.hedonism += 0.15;
    p.duty -= 0.1;
  }
  if (mods.optimism) {
    p.denial += 0.25;
    p.rage += 0.05;
  }
  if (mods.welfareChecks) p.quiet -= 0.1;
  if (mods.schoolsClosed && c.age >= 28 && c.age <= 50) {
    p.duty -= 0.1;
    p.hedonism += 0.05;
  }
  if (mods.legalizeAll) p.hedonism += 0.1;
  if (mods.pensionRaided) p.hedonism += 0.1;
  if (mods.priceControls) p.hoarding += 0.1;
  if (state.morale > 0.65) p.hedonism += 0.1;
  if (state.morale < 0.3) {
    p.quiet += 0.1;
    p.rage += 0.1;
  }
  // The object fills more of the sky each day. Anxious people feel it first.
  p.quiet += 0.3 * c.traits.anxious * clamp((day - 15) / 15);
  for (const s of COPING_STYLES) p[s] = Math.max(0, p[s]);
  return p;
}

export function bestStyle(p: Record<CopingStyle, number>, exclude: CopingStyle | null = null): CopingStyle {
  let best: CopingStyle = "duty";
  let bestV = -1;
  for (const s of COPING_STYLES) {
    if (s === exclude) continue;
    if (p[s] > bestV) {
      bestV = p[s];
      best = s;
    }
  }
  return best;
}

export interface Switch {
  id: number;
  from: CopingStyle;
  to: CopingStyle;
}

export function updateCoping(state: TownState, rng: Rng, mods: Modifiers): Switch[] {
  const mix = streetMix(state);
  const switched: Switch[] = [];
  for (const c of state.citizens) {
    if (!c.present) continue;
    const p = pressures(state, c, mix, mods);
    const best = bestStyle(p);
    if (best === c.coping) continue;
    if (best === "quiet" && c.traits.anxious < 0.3) continue;
    // People tire of a way of coping; duty and quiet are the ones that settle in.
    const tenure = Math.min(12, state.day - c.copingSince);
    const fatigue = c.coping === "duty" || c.coping === "quiet" ? 1 : 1 - 0.025 * tenure;
    const current = p[c.coping] * fatigue;
    let threshold = 1.15 + 0.5 * c.traits.stubborn;
    if (c.coping === "quiet") threshold = 2.0;
    else if (best === "quiet") threshold = 1.0;
    if (p[best] > current * threshold && rng.chance(0.5)) {
      switched.push({ id: c.id, from: c.coping, to: best });
      c.coping = best;
      c.copingSince = state.day;
      if (best === "quiet") c.working = false;
      else if (c.dept && !c.working && c.strikeUntil <= state.day && !c.tags.includes("volunteer")) c.working = true;
    }
  }
  for (const row of state.streetPulse) for (let k = 0; k < row.length; k++) row[k] = (row[k] ?? 0) * 0.5;
  return switched;
}

export function updateMoods(state: TownState, rng: Rng, mods: Modifiers): void {
  for (const c of state.citizens) {
    if (!c.present) continue;
    const street = state.streets[c.street];
    let d = 0.1 * (state.morale - 0.5);
    if (street && !street.water) d -= 0.1;
    if (street && !street.power) d -= 0.08;
    switch (c.coping) {
      case "hedonism":
        d += 0.05;
        break;
      case "quiet":
        d -= 0.05;
        break;
      case "duty":
        d += 0.02;
        break;
      case "piety":
        d += 0.03;
        break;
      case "rage":
        d -= 0.03;
        break;
      default:
        break;
    }
    if (mods.holiday) d += 0.02;
    if (mods.curfew && c.coping === "hedonism") d -= 0.03;
    d -= 0.06 * clamp((state.day - 18) / 12);
    d += rng.gauss() * 0.04;
    c.mood = clamp(c.mood * 0.95 + d, -1, 1);
    c.trustOffset *= 0.9;
    if (state.day >= 10) {
      c.beliefs.real = clamp(c.beliefs.real + (1 - c.beliefs.real) * 0.08);
      c.beliefs.miss = clamp(c.beliefs.miss * 0.92);
    }
  }
}

export function copingCounts(state: TownState): Record<CopingStyle, number> {
  const out = {} as Record<CopingStyle, number>;
  for (const s of COPING_STYLES) out[s] = 0;
  for (const c of state.citizens) if (c.present) out[c.coping]++;
  return out;
}

export function presentCount(state: TownState): number {
  let n = 0;
  for (const c of state.citizens) if (c.present) n++;
  return n;
}

export function copingFraction(state: TownState, style: CopingStyle): number {
  const n = presentCount(state);
  return n ? copingCounts(state)[style] / n : 0;
}

export function dominantStyle(state: TownState): CopingStyle {
  const counts = copingCounts(state);
  return bestStyle(counts);
}
