export const TEMPLATE_IDS = (): string[] => Object.keys(T);

const STYLE_TEMPLATES: Record<CopingStyle, Array<[string, number]>> = {
  denial: [["permit.routine", 4], ["complaint.lawn", 1], ["permit.divorce", 1], ["appeal.fine", 1]],
  duty: [["welfare.check", 2], ["staffing.request", 2], ["ordinance.proposal", 1], ["request.overtime", 1], ["report.inventory", 1], ["request.plan", 1]],
  hedonism: [["permit.blockParty", 3], ["petition.holiday", 1], ["permit.fireworks", 2], ["request.pa", 1], ["permit.pool", 1]],
  piety: [["permit.vigil", 3], ["petition.rename", 1], ["request.bells", 1], ["permit.baptism", 1], ["request.key", 1]],
  rage: [["complaint.everything", 3], ["question.bunker", 1], ["strike", 2], ["permit.divorce", 1], ["complaint.font", 1], ["demand.list", 1], ["petition.recall", 1], ["request.plan", 1]],
  hoarding: [["permit.grocer", 3], ["complaint.counting", 1], ["request.warehouse", 1]],
  flight: [["resignation", 5], ["records.birthCert", 2], ["transfer.house", 1], ["request.map", 1]],
  confession: [["confession", 1]],
  bargaining: [["question.real", 2], ["petition.cancel", 1], ["petition.rename", 1], ["petition.holiday", 1], ["proposal.mirror", 1], ["request.key", 1]],
  quiet: [],
};

const ACT_PROB: Record<CopingStyle, number> = {
  denial: 0.05,
  duty: 0.05,
  hedonism: 0.06,
  piety: 0.05,
  rage: 0.07,
  hoarding: 0.06,
  flight: 0.08,
  confession: 0.1,
  bargaining: 0.06,
  quiet: 0,
};

const FALLBACK: Array<[string, number]> = [["permit.routine", 2], ["complaint.everything", 1], ["question.bunker", 1], ["complaint.lawn", 1]];

/** Pick a template for a style, preferring ones the month has seen less of and skipping ones that have run out. */
function weightedPick(state: TownState, rng: Rng, items: Array<[string, number]>): string {
  const open = items.filter(([id]) => {
    const t = T[id];
    const cap = t?.maxPerMonth ?? 10;
    return (state.used[`n:${id}`] ?? 0) < cap && (!t?.minDay || state.day >= t.minDay);
  });
  const weighted = (open.length ? open : FALLBACK).map(([id, w]) => [id, w / (1 + (state.used[`n:${id}`] ?? 0))] as [string, number]);
  const total = weighted.reduce((a, [, w]) => a + w, 0);
  let r = rng.next() * total;
  for (const [id, w] of weighted) {
    r -= w;
    if (r <= 0) return id;
  }
  return weighted[weighted.length - 1]?.[0] ?? "permit.routine";
}

const MAX_ACTIVE_STORIES = 5;

function startStories(state: TownState, rng: Rng): void {
  const tomorrow = state.day + 1;
  let active = state.stories.filter((s) => !s.done).length;
  for (const def of STORIES) {
    if (state.stories.some((s) => s.id === def.id)) continue;
    if (tomorrow < def.window[0] || tomorrow > def.window[1]) continue;
    if (active >= MAX_ACTIVE_STORIES && !def.important) continue;
    if (!rng.chance(def.chance)) continue;
    const params = def.start(state, rng);
    if (!params) continue;
    state.stories.push({ id: def.id, params, beat: 0, nextDay: tomorrow, choices: [], done: false });
    active++;
  }
}

function advanceStories(state: TownState, rng: Rng, out: Document[]): void {
  const tomorrow = state.day + 1;
  for (const story of state.stories) {
    if (story.done || story.nextDay === 0 || story.nextDay > tomorrow) continue;
    const def = STORIES.find((d) => d.id === story.id);
    if (!def) {
      story.done = true;
      continue;
    }
    while (story.beat < def.beats.length) {
      const beat = def.beats[story.beat]!;
      if (beat.when && !beat.when(state, story)) {
        story.beat++;
        continue;
      }
      const params: Params = { ...story.params, ...(beat.params?.(state, story) ?? {}), story: story.id, beatIndex: story.beat };
      const doc = createDoc(state, rng, beat.template, params);
      if (!doc) {
        story.choices[story.beat] = "skipped";
        story.beat++;
        continue;
      }
      out.push(doc);
      story.nextDay = 0;
      break;
    }
    if (story.beat >= def.beats.length) story.done = true;
  }
}

/** Called when a story document is resolved or lapses: record the choice and schedule the next beat. */
function storyResolved(state: TownState, rng: Rng, doc: Document, option: string): void {
  const story: Story | null = storyOf(state, doc);
  if (!story) return;
  const beatIndex = Number(doc.payload.beatIndex);
  if (!Number.isFinite(beatIndex)) return;
  story.choices[beatIndex] = option;
  const def = STORIES.find((d) => d.id === story.id);
  if (!def) return;
  story.beat = beatIndex + 1;
  if (story.beat >= def.beats.length) {
    story.done = true;
    story.nextDay = 0;
    return;
  }
  const next = def.beats[story.beat]!;
  const byDelay = state.day + (next.delay ? rng.int(next.delay[0], next.delay[1]) : 1);
  story.nextDay = next.at ? Math.max(state.day + 1, rng.int(next.at[0], next.at[1])) : byDelay;
}

/** Documents the town generates today for tomorrow's in-tray. */
export function generateDailyDocs(state: TownState, rng: Rng): Document[] {
  const out: Document[] = [];
  const add = (template: string, params: Params) => {
    const d = createDoc(state, rng, template, params);
    if (d) out.push(d);
  };
  const tomorrow = state.day + 1;
  if ([2, 5, 9, 14, 20, 27].includes(tomorrow)) add("federal.memo", {});
  if (tomorrow % 7 === 0 && tomorrow <= 28) add("budget.weekly", {});
  if ([3, 10, 20].includes(tomorrow)) add("editor.interview", {});
  if (state.services.water < 0.7) add("engineer.memo", {});
  if (state.order < 0.4 && !isActive(state, "curfew") && rng.chance(0.5)) add("ordinance.proposal", { ord: "curfew", chief: true });

  for (const c of state.citizens) {
    if (!c.present || c.role !== "council") continue;
    if (rng.chance(state.day <= 3 ? 0.5 : 0.22)) add("ordinance.proposal", { c: c.id });
  }

  startStories(state, rng);
  advanceStories(state, rng, out);
  out.push(...dailyIncidents(state, rng));

  // The last ten days have their own paperwork, whoever is left to file it.
  if (tomorrow >= 20) for (let i = 0; i < (tomorrow >= 25 ? 2 : 1); i++) add(weightedPick(state, rng, LATE_POOL), {});
  if (tomorrow === 29) add("late.selfResign", {});

  for (const c of state.citizens) {
    if (!c.present || c.coping === "quiet" || c.role === "council") continue;
    const last = state.used[`c:${c.id}`];
    if (last !== undefined && state.day - last < 2) continue;
    let p = ACT_PROB[c.coping] * (1 + state.day / 30);
    if (c.coping === "flight" && c.dept && !c.tags.includes("resigning")) p = 0.6;
    if (!rng.chance(p)) continue;
    const pool = STYLE_TEMPLATES[c.coping];
    if (pool.length === 0) continue;
    add(weightedPick(state, rng, pool), { c: c.id });
  }
  return out;
}

export function resolveDoc(state: TownState, rng: Rng, doc: Document, option: string): void {
  const t = T[doc.template];
  if (!t) throw new Error(`unknown document template: ${doc.template}`);
  if (option === "defer") {
    doc.age++;
    doc.priority += 1;
    doc.chosen = "defer";
    const sender = cit(state, doc.sender);
    if (sender) {
      mood(sender, -0.1);
      trustOf(sender, -0.05);
    }
    doc.body += `\n\nDEFERRED. Resubmitted. The applicant has added a note: "${doc.age === 1 ? "still waiting" : doc.age === 2 ? "still here" : "hello"}."`;
    state.kpis.deferrals++;
    return;
  }
  doc.status = "resolved";
  doc.chosen = option;
  doc.resolvedDay = state.day;
  doc.outcome = t.resolve({ state, rng }, doc, option);
  state.kpis.permitsProcessed++;
  if (option === "approve") state.kpis.permitsApproved++;
  if (option === "deny") state.kpis.permitsDenied++;
  storyResolved(state, rng, doc, option);
}

export function lapseDoc(state: TownState, rng: Rng, doc: Document): void {
  const t = T[doc.template];
  doc.status = "lapsed";
  doc.resolvedDay = state.day;
  doc.outcome = t?.lapse ? t.lapse({ state, rng }, doc) : "Unprocessed. It resolved itself, as things do.";
  state.kpis.lapsed++;
  storyResolved(state, rng, doc, "lapsed");
}

export function initialInTray(state: TownState, rng: Rng): Document[] {
  const out: Document[] = [];
  const add = (template: string, params: Params) => {
    const d = createDoc(state, rng, template, params);
    if (d) out.push(d);
  };
  add("charter", {});
  add("permit.routine", {});
  add("permit.routine", {});
  const order = state.citizens.find((c) => c.role === "council" && c.agenda === "order");
  if (order) add("ordinance.proposal", { c: order.id, ord: "rationing" });
  add("federal.memo", {});
  add("resignation", {});
  add("question.real", {});
  add("permit.blockParty", {});
  return out;
}
