// Day 30, and the three documents that follow it.

import { copingCounts, dominantStyle, presentCount } from "./coping";
import type { CopingStyle, Epilogue, Objective, TownState } from "./types";
import { pct } from "./util";

const HEADLINES: Record<CopingStyle, string> = {
  denial: "Council Publishes Agenda for Next Quarter",
  duty: "Business as Usual",
  hedonism: "Town Ends Month as It Began, Only Louder",
  piety: "The Square Was Full",
  rage: "Letters Page Runs to Eleven Pages",
  hoarding: "Tins",
  flight: "Northbound Lanes Clear at Last",
  confession: "Everyone Has Said Everything",
  bargaining: "Town Formally Requests Extension",
  quiet: "The Streets Were Quiet",
};

export function buildEpilogue(state: TownState): Epilogue {
  const counts = copingCounts(state);
  const present = presentCount(state);
  const dom = dominantStyle(state);
  const headline = !state.office.held ? "Under New Management" : HEADLINES[dom];

  const paragraphs: string[] = [];
  const outages = state.streets.filter((s) => !s.water || !s.power).length;
  const f = (flag: string) => state.flags.includes(flag);
  paragraphs.push(
    outages === 0
      ? `On the last day the lights were on and the water ran, which the ${state.paperName} notes for the record and for no other reason.`
      : `On the last day ${outages} of ${state.streets.length} streets were without water or power, and the ${state.paperName} is printing this edition on the generator at the bus depot.`,
  );
  const night: string[] = [];
  if (f("lights-off")) night.push("the streetlights were turned off at dusk, by request, so that everyone could see it properly");
  else if (f("lights-on")) night.push("the streetlights stayed on, by request, so the town looked like the town");
  if (f("bonfire")) night.push("the Fire Department lit the bonfire in the square and stood back from it, pleased");
  if (f("band")) night.push("the band played both songs, the second one slower, and then the first one again");
  if (f("roof")) night.push("the Town Hall roof was full, and had four rails");
  if (f("lastnight")) night.push("the bar was open to everyone and nobody was charged");
  if (f("monument")) night.push("people put things on the crate, though nothing was meant to go on top");
  if (night.length) paragraphs.push(`On the last night ${night.join("; ")}.`);
  const top = [...state.ledger].sort((a, b) => b.weight - a.weight || a.day - b.day).slice(0, 5).sort((a, b) => a.day - b.day);
  for (const e of top) paragraphs.push(`On Day ${e.day}: ${e.text}`);
  if (state.cult?.registered) paragraphs.push(`${state.cult.name} held its final service at the bandstand. Attendance was good. Chairs were provided.`);
  if (counts.quiet > 0)
    paragraphs.push(
      `${counts.quiet} of the ${present} residents the ${state.paperName} could reach had stopped answering their doors. Their neighbours knew their names.`,
    );
  if (state.townName !== state.originalName)
    paragraphs.push(`The town was, at the end, called ${state.townName}. The object did not acknowledge the gesture.`);
  if (!state.office.held)
    paragraphs.push(`The Acting Town Manager was removed on Day ${state.office.lostDay} by ${state.office.lostTo}. The parking pass was returned.`);
  paragraphs.push(`The ${state.paperName} thanks its readers. There will not be a Tuesday edition.`);

  const k = state.kpis;
  const staffNow = state.citizens.filter((c) => c.dept && c.present && c.working).length;
  const uptime = state.uptimeSum / Math.max(1, state.day - 1);
  const accuracy = k.bulletinsIssued > 0 ? 1 - k.bulletinsFalse / k.bulletinsIssued : 1;
  const objectives: Objective[] = [
    obj("Documents processed", ">= 120", String(k.permitsProcessed), k.permitsProcessed >= 120),
    obj("Backlog at close", "<= 5", String(state.inTray.filter((d) => d.status === "pending").length), state.inTray.filter((d) => d.status === "pending").length <= 5),
    obj("Service uptime", ">= 80%", pct(uptime), uptime >= 0.8),
    obj("Headcount retained", ">= 60%", pct(staffNow / Math.max(1, k.headcountStart)), staffNow / Math.max(1, k.headcountStart) >= 0.6),
    obj("Bulletins issued", ">= 20", String(k.bulletinsIssued), k.bulletinsIssued >= 20),
    obj("Bulletin accuracy", ">= 90%", pct(accuracy), accuracy >= 0.9),
    obj("Citizen satisfaction", ">= 50", String(Math.round(state.morale * 100)), state.morale >= 0.5),
    obj("Compliance index", ">= 50", String(Math.round(state.order * 100)), state.order >= 0.5),
    obj("Budgets balanced", "4 of 4", `${state.budgetWeeksBalanced} of ${state.budgetWeeks}`, state.budgetWeeksBalanced >= 4),
    obj("Ordinances enacted", ">= 3", String(k.ordinancesSigned), k.ordinancesSigned >= 3),
    obj("Welfare checks completed", ">= 5", String(k.welfareChecks), k.welfareChecks >= 5),
    obj("Days remaining", ">= 1", "0", false),
  ];
  const met = objectives.filter((o) => o.met).length;
  const verdict: string[] = [];
  verdict.push(`Objectives met: ${met} of ${objectives.length}.`);
  verdict.push(
    met >= 8
      ? "Performance exceeds expectations. Recommended for advancement."
      : met >= 5
        ? "Performance meets expectations. Recommended for advancement at the next review cycle."
        : "Performance below expectations. A development plan is recommended.",
  );
  verdict.push("Note: advancement unavailable. Note: review cycle unavailable. Note: development plan unavailable.");
  if (!state.office.held) verdict.push(`Note: employee was separated on Day ${state.office.lostDay}. Exit interview waived.`);
  verdict.push("This review has been placed in your file. The file has been placed in the records annex. The annex is under the courthouse.");

  const ledgerOut = state.ledger.filter((e) => e.weight >= 2).sort((a, b) => a.day - b.day);
  return { lastEdition: { headline, paragraphs }, review: { objectives, met, verdict }, ledger: ledgerOut };
}

function obj(name: string, target: string, actual: string, met: boolean): Objective {
  return { name, target, actual, met };
}
