incident({
  id: "tower",
  minDay: 9,
  chance: 0.45,
  maxPerMonth: 1,
  fire: (s, rng) => {
    const word = rng.pick(["SORRY", "THANKS", "WELL", "BYE", "PLEASE"]);
    paper(s, `Water Tower Repainted Overnight; Now Reads "${word}"`, `The water tower on Mill Road was repainted overnight by persons unknown and now reads, in letters visible from the highway, ${word}. The Water Department has confirmed that the water is unaffected and that the word is "a fair summary."`, 3);
    pulseAll(s, "bargaining", 0.05);
    return createDoc(s, rng, "incident.tower", { word });
  },
});

define("incident.tower", {
  make: (ctx, p) => {
    const c = senderOf(ctx, p, (x) => x.coping === "duty" || x.coping === "piety" || x.coping === "denial");
    if (!c) return null;
    return {
      kind: "petition",
      title: "Request: Leave the Water Tower As It Is",
      body: `${nm(c)} asks that the water tower, now reading ${String(p.word)}, be left as it is and not repainted, ${c.first} having "come round to it." ${c.first} notes that the previous lettering said ${ctx.state.originalName.toUpperCase()} and that "we knew that."`,
      options: [
        { id: "leave", label: "Leave it" },
        { id: "repaint", label: "Repaint it" },
      ],
      sender: c.id,
      senderLabel: nm(c),
      priority: 2,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const word = String(doc.payload.word);
    if (option === "leave") {
      s.flags.push(`tower-${word}`);
      ledger(s, `The water tower was left reading ${word}.`, [], 2);
      return `Left. The tower says ${word}, and will.`;
    }
    s.treasury -= 3;
    paper(s, `Water Tower Repainted; Now Reads "${word}" Again, Larger`, `The Town repainted the water tower yesterday to restore the original lettering. By morning it read ${word} again, larger, in a better hand. The Water Department has stopped commenting.`, 2);
    return `Repainted. By morning it said ${word} again, larger.`;
  },
});

incident({
  id: "independence",
  minDay: 12,
  chance: 0.5,
  maxPerMonth: 1,
  when: (s) => copingFraction(s, "rage") > 0.1,
  fire: (s, rng) => {
    const counts = s.streets.map((st) => s.citizens.filter((c) => c.present && c.street === st.id && c.coping === "rage").length);
    let best = 1;
    for (let i = 1; i < counts.length; i++) if ((counts[i] ?? 0) > (counts[best] ?? 0)) best = i;
    const name = sname(s, best);
    paper(s, `${name} Declares Independence; Border Is a Bin`, `Residents of ${name} declared the street an independent republic at a meeting on Tuesday and have placed a bin across the junction as a border. A flag has been raised. It is a towel. Customs are being enforced by a child.`, 3);
    return createDoc(s, rng, "incident.independence", { street: best });
  },
});

define("incident.independence", {
  make: (ctx, p) => {
    const st = Number(p.street ?? 1);
    const c = senderOf(ctx, p, (x) => x.street === st);
    if (!c) return null;
    return {
      kind: "petition",
      title: `Declaration of Independence: ${sname(ctx.state, st)}`,
      body: `The Republic of ${sname(ctx.state, st)}, through its provisional president ${nm(c)}, gives notice of its secession from the Town, citing the bulletins, the bins, and "everything." The Republic seeks recognition, a seat at the table, and continued refuse collection, "as a courtesy between nations."`,
      options: [
        { id: "recognize", label: "Recognise the Republic" },
        { id: "refuse", label: "Refuse" },
        { id: "annex", label: "Send the police" },
      ],
      sender: c.id,
      senderLabel: `${nm(c)}, Provisional President`,
      priority: 4,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const st = Number(doc.payload.street ?? 1);
    const c = cit(s, doc.sender);
    const name = sname(s, st);
    if (option === "recognize") {
      s.morale = clamp(s.morale + 0.02);
      s.order = clamp(s.order - 0.03);
      pulse(s, st, "rage", -0.3);
      pulse(s, st, "hedonism", 0.2);
      ledger(s, `The Town recognised the Republic of ${name}. Trade relations were established over the bin. Refuse collection continues as a courtesy between nations.`, c ? [nm(c)] : [], 3);
      paper(s, `Town Recognises Republic of ${name}; Trade Talks Held Over Bin`, `The Town has formally recognised the independence of ${name}. A treaty was signed on the bin. The Republic's first act was to declare a holiday. Its second was to ask for the bins to be emptied, which they were.`, 3);
      return `Recognised. A treaty was signed on the bin. The Republic has asked for its bins to be emptied, and they have been.`;
    }
    if (option === "annex") {
      if (s.services.police > 0.5) {
        s.order = clamp(s.order + 0.05);
        pulse(s, st, "rage", 0.2);
        paper(s, `Police Reclaim ${name}; Bin Moved; Towel Confiscated`, `Officers entered the Republic of ${name} yesterday morning, moved the bin, and confiscated the flag, which was a towel. The child enforcing customs was given a hat. The republic has gone underground, into the garages.`, 2);
        return "The police moved the bin. The towel has been confiscated. The child has a hat.";
      }
      s.order = clamp(s.order - 0.03);
      return "Two officers attended, looked at the bin, and declined to move it, there being two of them and it being a bin with a republic behind it.";
    }
    pulse(s, st, "rage", 0.2);
    return `Refused. The Republic of ${name} has closed its border, which is still a bin.`;
  },
});

