incident({
  id: "sickout",
  minDay: 10,
  chance: 0.4,
  maxPerMonth: 1,
  when: (s) => copingFraction(s, "duty") < 0.25,
  fire: (s, rng) => {
    let n = 0;
    for (const c of s.citizens) {
      if (c.dept && c.present && c.working && c.role === null && rng.chance(0.25)) {
        c.strikeUntil = s.day + 1;
        c.working = false;
        n++;
      }
    }
    paper(s, `Mass Sickout at Town Hall; Symptoms "General"`, `${n} municipal employees called in sick this morning with symptoms described, in every case, as general. The Records Department, which took the calls, has recorded them as "general." Services are reduced for the day.`, 2);
    return null;
  },
});

