incident({
  id: "arkqueue",
  minDay: 1,
  chance: 0.4,
  maxPerMonth: 1,
  when: (s) => s.citizens.some((c) => c.present && c.tags.includes("ark")),
  fire: (s) => {
    const owner = s.citizens.find((c) => c.present && c.tags.includes("ark"));
    if (!owner) return null;
    paper(s, "Visitors Queue to See Vessel; Owner Charges Admission in Tins", `A queue formed on ${sname(s, owner.street)} yesterday to view the vessel under construction at ${addr(s, owner)}. ${nm(owner)} has begun charging admission, one tin, and giving a tour, which ends at the goat. Visitors report the goat as "the highlight."`, 2);
    mood(owner, 0.1);
    return null;
  },
});

/** Fire today's incidents. Returns documents for tomorrow's tray. */
export function dailyIncidents(state: TownState, rng: Rng): Document[] {
  const out: Document[] = [];
  const heat = 0.5 + absurdity(state);
  let fired = 0;
  const candidates = rng.shuffle(INCIDENTS.filter((i) => state.day >= i.minDay && (state.used[`inc:${i.id}`] ?? 0) < i.maxPerMonth && (!i.when || i.when(state))));
  for (const inc of candidates) {
    if (fired >= 2) break;
    if (!rng.chance(inc.chance * heat * 0.6)) continue;
    state.used[`inc:${inc.id}`] = (state.used[`inc:${inc.id}`] ?? 0) + 1;
    const d = inc.fire(state, rng);
    if (d) out.push(d);
    fired++;
  }
  return out;
}
