export const ORDINANCE_IDS = Object.keys(ORDINANCES) as OrdinanceId[];

export function isActive(state: TownState, id: OrdinanceId): boolean {
  return state.ordinances.some((o) => o.id === id && o.active);
}

export function modifiers(state: TownState): Modifiers {
  return {
    curfew: isActive(state, "curfew"),
    rationing: isActive(state, "rationing"),
    priceControls: isActive(state, "priceControls"),
    schoolsClosed: isActive(state, "closeSchools"),
    barsOpen: isActive(state, "openBars"),
    optimism: isActive(state, "optimism"),
    legalizeAll: isActive(state, "legalizeAll"),
    holiday: isActive(state, "holiday"),
    payrollFreeze: isActive(state, "payrollFreeze"),
    pensionRaided: isActive(state, "raidPension"),
    welfareChecks: isActive(state, "welfareChecks"),
    banHoarding: isActive(state, "banHoarding"),
  };
}

export function signOrdinance(state: TownState, rng: Rng, id: OrdinanceId, by: string): void {
  if (isActive(state, id)) return;
  const def = ORDINANCES[id];
  const delay = rng.int(def.exploitDelay[0], def.exploitDelay[1]);
  state.ordinances.push({ id, signedDay: state.day, exploitDay: state.day + delay, exploited: false, active: true, by });
  state.kpis.ordinancesSigned++;
  switch (id) {
    case "curfew":
      state.order = clamp(state.order + 0.08);
      state.morale = clamp(state.morale - 0.05);
      break;
    case "rationing":
      state.morale = clamp(state.morale - 0.03);
      break;
    case "priceControls":
      state.morale = clamp(state.morale + 0.05);
      state.treasury -= 5;
      break;
    case "closeSchools": {
      state.morale = clamp(state.morale - 0.03);
      const principal = state.citizens.find((c) => c.role === "principal" && c.present);
      if (principal) {
        principal.mood = clamp(principal.mood - 0.4, -1, 1);
        principal.trustOffset -= 0.2;
        ledger(state, `${fullName(principal)} was informed of the school closure by memo and replied by memo.`, [fullName(principal)], 1);
      }
      break;
    }
    case "openBars":
      state.morale = clamp(state.morale + 0.08);
      state.order = clamp(state.order - 0.05);
      break;
    case "optimism":
      state.trust = clamp(state.trust - 0.02);
      break;
    case "legalizeAll": {
      state.order = clamp(state.order - 0.1);
      const police = state.departments.find((d) => d.id === "police");
      if (police) police.required = 6;
      pulseAll(state, "rage", -0.1);
      break;
    }
    case "holiday":
      state.morale = clamp(state.morale + 0.08);
      break;
    case "payrollFreeze":
      for (const c of state.citizens) if (c.dept && c.present) c.prop.flight = clamp(c.prop.flight + 0.2);
      break;
    case "raidPension": {
      state.treasury += 60;
      state.morale = clamp(state.morale + 0.15);
      const actuary = state.citizens.find((c) => c.role === "actuary" && c.present && c.dept === "pension");
      if (actuary) {
        actuary.dept = null;
        actuary.working = false;
        actuary.tags.push("resigned");
        ledger(
          state,
          `${fullName(actuary)} resigned as actuary in protest at the pension reallocation and took the ledger, which was a spreadsheet, which was also on the server.`,
          [fullName(actuary)],
          3,
        );
      }
      break;
    }
    case "welfareChecks":
      break;
    case "banHoarding":
      state.order = clamp(state.order - 0.02);
      break;
  }
  ledger(state, `${def.name} signed, on the proposal of ${by}.`, [], 2);
  paper(state, `${def.name} Signed`, `${def.proposal} Effective immediately. The Town thanks residents for their cooperation in advance.`, 2);
}

export function repealOrdinance(state: TownState, id: OrdinanceId): void {
  for (const o of state.ordinances) if (o.id === id && o.active) o.active = false;
  if (id === "legalizeAll") {
    const police = state.departments.find((d) => d.id === "police");
    if (police) police.required = 12;
  }
}

export interface ExploitRequest {
  template: string;
  params: Params;
}

/** Fire any exploits that have come due. Returns documents to put in tomorrow's in-tray. */
export function dueExploits(state: TownState, rng: Rng): ExploitRequest[] {
  const out: ExploitRequest[] = [];
  const streetName = (i: number) => state.streets[i]?.name ?? "Main Street";
  for (const o of state.ordinances) {
    if (!o.active || o.exploited || state.day < o.exploitDay) continue;
    o.exploited = true;
    const s = rng.int(0, state.streets.length - 1);
    switch (o.id) {
      case "curfew":
        out.push({ template: "exploit.vigilBar", params: {} });
        paper(state, "Bars Find Religion", `Three licensed premises have applied for recognition as places of worship under the curfew exemption. Services nightly, ten until six. A spokesman said the congregation was "regular."`, 3);
        break;
      case "rationing":
      case "banHoarding":
        for (let i = 0; i < 3; i++) out.push({ template: "permit.grocer", params: { exploit: true } });
        paper(state, "Forty-One New Grocers Register in a Single Day", `Applications for commercial grocer's licences rose from zero to forty-one following the ordinance. Most premises are garages. One is a car.`, 3);
        pulseAll(state, "hoarding", 0.15);
        break;
      case "priceControls":
        out.push({ template: "exploit.closure", params: {} });
        paper(state, `Market Closes "For Inventory"`, `The town's largest grocer closed its doors this morning citing a need to count things. Staff were seen loading a van. A sign reads BACK SOON in a hand that did not mean it.`, 3);
        pulseAll(state, "hoarding", 0.3);
        state.morale = clamp(state.morale - 0.05);
        break;
      case "closeSchools":
        out.push({ template: "exploit.academy", params: { street: s } });
        break;
      case "openBars":
        out.push({ template: "complaint.noise", params: { street: s } });
        out.push({ template: "complaint.noise", params: { street: (s + 3) % state.streets.length } });
        state.morale = clamp(state.morale - 0.02);
        break;
      case "optimism":
        out.push({ template: "exploit.optimismOfficer", params: { street: s } });
        out.push({ template: "exploit.optimismOfficer", params: { street: (s + 5) % state.streets.length } });
        paper(state, `Frowning Cited on ${streetName(s)}`, `Volunteers enforcing the Mandatory Optimism Ordinance issued their first written warnings yesterday. One recipient was reportedly "thinking about it." Appeals may be lodged cheerfully.`, 3);
        break;
      case "legalizeAll":
        out.push({ template: "complaint.noise", params: { street: s, fireworks: true } });
        paper(state, "Fireworks Now Legal; Fireworks Now Everywhere", `With permits abolished, residents report a continuous display over ${streetName(s)} since dusk. The Fire Department has asked that it be noted it still exists.`, 3);
        state.order = clamp(state.order - 0.1);
        break;
      case "holiday":
        out.push({ template: "petition.everyDay", params: {} });
        break;
      case "payrollFreeze": {
        out.push({ template: "exploit.volunteers", params: {} });
        let n = 0;
        for (const c of state.citizens) {
          if (c.dept && c.present && c.working && rng.chance(0.3)) {
            c.working = false;
            c.tags.push("volunteer");
            n++;
          }
        }
        paper(state, "Municipal Staff Re-register as Volunteers", `${n} employees have re-registered as volunteers following the payroll suspension, and have volunteered, for the time being, to stay home.`, 3);
        break;
      }
      case "raidPension":
        out.push({ template: "permit.liquidationParty", params: { street: s } });
        break;
      case "welfareChecks":
        out.push({ template: "exploit.welfareTownHall", params: {} });
        break;
    }
    pulse(state, s, "bargaining", 0.1);
  }
  return out;
}
