// The window behind the desk. The only beautiful thing in the game is the object in it getting larger.

function hex(c: string): [number, number, number] {
  const n = parseInt(c.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function lerpColor(a: string, b: string, t: number): string {
  const [r1, g1, b1] = hex(a);
  const [r2, g2, b2] = hex(b);
  const r = Math.round(r1 + (r2 - r1) * t);
  const g = Math.round(g1 + (g2 - g1) * t);
  const bb = Math.round(b1 + (b2 - b1) * t);
  return `rgb(${r},${g},${bb})`;
}

export function skySvg(day: number, ended = false): string {
  const t = Math.min(1, Math.max(0, (day - 1) / 29));
  const w = 240;
  const h = 150;
  const r = ended ? 140 : 2.5 + 58 * Math.pow(t, 2.1);
  const top = lerpColor("#a7c8e6", "#4a3b63", t);
  const mid = lerpColor("#d2e2ee", "#8d6c7e", t);
  const bot = lerpColor("#eef1f0", "#c9a08b", t);
  const glow = 0.12 + 0.3 * t;
  const cx = w * 0.64;
  const cy = h * 0.4;
  const hills = `M0,${h * 0.78} C ${w * 0.15},${h * 0.7} ${w * 0.3},${h * 0.82} ${w * 0.45},${h * 0.76} S ${w * 0.75},${h * 0.7} ${w},${h * 0.8} L${w},${h} L0,${h} Z`;
  const town = Array.from({ length: 11 }, (_, i) => {
    const x = 8 + i * 22;
    const bh = 10 + ((i * 7) % 5) * 4;
    return `<rect x="${x}" y="${h * 0.78 - bh}" width="14" height="${bh + 6}" fill="#3a3630"/><rect x="${x + 4}" y="${h * 0.78 - bh + 4}" width="3" height="3" fill="${t > 0.5 ? "#f2d27a" : "#e9e2c8"}" opacity="${0.5 + 0.5 * t}"/>`;
  }).join("");
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="The window. Day ${day}.">
  <defs>
    <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="${top}"/><stop offset="0.55" stop-color="${mid}"/><stop offset="1" stop-color="${bot}"/>
    </linearGradient>
    <radialGradient id="glow"><stop offset="0" stop-color="#fff2d6" stop-opacity="${glow}"/><stop offset="1" stop-color="#fff2d6" stop-opacity="0"/></radialGradient>
  </defs>
  <rect width="${w}" height="${h}" fill="url(#sky)"/>
  <circle cx="${cx}" cy="${cy}" r="${r * 2.4 + 10}" fill="url(#glow)"/>
  <circle cx="${cx}" cy="${cy}" r="${r}" fill="#2b2622"/>
  <circle cx="${cx - r * 0.3}" cy="${cy - r * 0.3}" r="${r * 0.55}" fill="#3a332d" opacity="0.6"/>
  <path d="${hills}" fill="#5e6a55"/>
  ${town}
  <rect x="0" y="0" width="${w}" height="${h}" fill="none" stroke="#2b2a26" stroke-width="6"/>
  <line x1="${w / 2}" y1="0" x2="${w / 2}" y2="${h}" stroke="#2b2a26" stroke-width="4"/>
  <line x1="0" y1="${h / 2}" x2="${w}" y2="${h / 2}" stroke="#2b2a26" stroke-width="4"/>
</svg>`;
}
