// Title screen, the evening paper, and the three closing documents.

import type { TownState } from "../sim/types";
import { h, paragraphs } from "./dom";
import { skySvg } from "./sky";
import { squarePhoto } from "./square";

export function renderTitle(hasSave: boolean, onBegin: (seed: number) => void, onContinue: () => void): HTMLElement {
  const seedInput = h("input", { type: "text", class: "seed", placeholder: "Seed (optional)", "aria-label": "Seed" }) as HTMLInputElement;
  const begin = () => {
    const raw = seedInput.value.trim();
    const seed = raw ? (Number.isFinite(Number(raw)) ? Number(raw) : hashSeed(raw)) : Math.floor(Math.random() * 1e9);
    onBegin(seed);
  };
  return h(
    "section",
    { class: "title-screen" },
    h("div", { class: "title-window", html: skySvg(1) }),
    h("p", { class: "title-office" }, "Office of the Town Manager (Acting)"),
    h("h1", { class: "title" }, "Business as Usual"),
    h("p", { class: "tagline" }, "The asteroid lands in thirty days. The pension fund still needs balancing."),
    h(
      "div",
      { class: "title-actions" },
      hasSave ? h("button", { class: "big", type: "button", onclick: onContinue }, "Continue the month") : null,
      h("button", { class: `big ${hasSave ? "secondary" : ""}`, type: "button", onclick: begin }, hasSave ? "Begin a new town" : "Report for duty"),
      seedInput,
    ),
    h("p", { class: "tiny title-note" }, "A playtest build. Thirty days, about thirty minutes. Saves itself. Keys 1 to 4 stamp; E ends the day."),
  );
}

function hashSeed(text: string): number {
  let hsh = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hsh ^= text.charCodeAt(i);
    hsh = Math.imul(hsh, 16777619);
  }
  return hsh >>> 0;
}

export function renderEvening(state: TownState, onNext: () => void): HTMLElement {
  const day = state.day - 1;
  const items = state.paper.filter((p) => p.day === day).sort((a, b) => b.weight - a.weight);
  const lead = items[0];
  const rest = items.slice(1, 5);
  const record = state.ledger.filter((e) => e.day === day && e.weight >= 2);
  const photo = squarePhoto(state, day);
  return h(
    "section",
    { class: "evening" },
    h(
      "article",
      { class: "paper" },
      h("header", { class: "masthead" }, h("h1", {}, state.paperName), h("p", { class: "dateline" }, `Evening edition. Day ${day} of 30. Price: whatever you have.`)),
      h("figure", { class: "photo" }, h("div", { class: "photo-img", html: photo.svg }), h("figcaption", {}, photo.caption)),
      lead ? h("div", { class: "lead" }, h("h2", {}, lead.headline), paragraphs(lead.body)) : h("div", { class: "lead" }, h("h2", {}, "A Quiet Day"), h("p", {}, "Nothing happened that this paper could print. The editor regards this as suspicious.")),
      rest.length ? h("div", { class: "columns" }, rest.map((p) => h("div", { class: "story" }, h("h3", {}, p.headline), h("p", {}, p.body)))) : null,
      record.length ? h("div", { class: "record" }, h("h3", {}, "For the record"), h("ul", {}, record.map((e) => h("li", {}, e.text)))) : null,
      h("div", { class: "paper-foot" }, h("button", { class: "big", type: "button", onclick: onNext }, state.ended ? "Close of business" : `Day ${state.day}`)),
    ),
  );
}

export function renderEpilogue(state: TownState, onNew: () => void): HTMLElement {
  const ep = state.epilogue;
  if (!ep) return h("section", { class: "evening" }, h("p", {}, "The month ended without paperwork, which is unlike it."));
  return h(
    "section",
    { class: "epilogue" },
    h("div", { class: "epilogue-window", html: skySvg(30, true) }),
    h(
      "article",
      { class: "paper" },
      h("header", { class: "masthead" }, h("h1", {}, state.paperName), h("p", { class: "dateline" }, "The last edition.")),
      h("figure", { class: "photo" }, h("div", { class: "photo-img", html: squarePhoto(state, 30).svg }), h("figcaption", {}, `The square, the last night. Photograph: the ${state.paperName}, from the ladder.`)),
      h("div", { class: "lead" }, h("h2", {}, ep.lastEdition.headline), ep.lastEdition.paragraphs.map((p) => h("p", {}, p))),
    ),
    h(
      "article",
      { class: "doc review" },
      h("header", { class: "doc-head" }, h("span", { class: "doc-form" }, "Form HR-30"), h("span", { class: "doc-day" }, "Confidential")),
      h("h1", {}, "Performance review"),
      h("p", { class: "doc-from" }, "Employee: Deputy Clerk (Acting Town Manager). Reviewer: unavailable."),
      h(
        "table",
        { class: "objectives" },
        h("thead", {}, h("tr", {}, h("th", {}, ""), h("th", {}, "Objective"), h("th", {}, "Target"), h("th", {}, "Actual"))),
        h("tbody", {}, ep.review.objectives.map((o) => h("tr", { class: o.met ? "met" : "" }, h("td", {}, o.met ? "☑" : "☐"), h("td", {}, o.name), h("td", {}, o.target), h("td", {}, o.actual)))),
      ),
      h("div", { class: "verdict" }, ep.review.verdict.map((v) => h("p", {}, v))),
      h("div", { class: "stamp-mark" }, "REVIEWED"),
    ),
    h(
      "article",
      { class: "doc memo ledger" },
      h("header", { class: "doc-head" }, h("span", { class: "doc-form" }, "The ledger"), h("span", { class: "doc-day" }, `${ep.ledger.length} entries`)),
      h("h1", {}, "Where it landed"),
      h("p", { class: "doc-from" }, "Every consequential stamp, and who it landed on. No score."),
      h("ul", { class: "ledger-list" }, ep.ledger.map((e) => h("li", {}, h("span", { class: "ledger-day" }, `Day ${e.day}`), h("span", {}, e.text)))),
    ),
    h("div", { class: "epilogue-foot" }, h("button", { class: "big", type: "button", onclick: onNew }, "Begin another month"), h("p", { class: "tiny" }, `Seed ${state.seed}. A different town next time.`)),
  );
}
