// Shared machinery for document templates: the registry, the context, and the small helpers every template uses.

import type { Rng } from "../rng";
import type { Citizen, DeptId, DocKind, DocOption, Document, Params, Story, TownState } from "../types";
import { clamp, fullName } from "../util";

export interface Ctx {
  state: TownState;
  rng: Rng;
}

export interface Draft {
  kind: DocKind;
  title: string;
  body: string;
  options: DocOption[];
  sender: number | null;
  senderLabel: string;
  priority: number;
}

export interface Template {
  /** Days that must pass before this template can be used again. */
  cooldown?: number;
  /** How many times this template may appear in one month. Default 8. */
  maxPerMonth?: number;
  /** Earliest day it may appear. */
  minDay?: number;
  make(ctx: Ctx, p: Params): Draft | null;
  resolve(ctx: Ctx, doc: Document, option: string): string;
  lapse?(ctx: Ctx, doc: Document): string;
}

export const T: Record<string, Template> = {};

export function define(id: string, t: Template): void {
  T[id] = t;
}

/** One beat of a story: a template, how long after the previous beat it arrives, and when it applies at all. */
export interface StoryBeat {
  template: string;
  /** Days after the previous beat resolves. Ignored for the first beat. */
  delay?: [number, number];
  /** An absolute day window instead of a delay. */
  at?: [number, number];
  when?: (state: TownState, story: Story) => boolean;
  params?: (state: TownState, story: Story) => Params;
}

export interface StoryDef {
  id: string;
  /** Days on which the story may begin. */
  window: [number, number];
  /** Chance per eligible day that it begins. */
  chance: number;
  /** Starts even when several stories are already running. */
  important?: boolean;
  start(state: TownState, rng: Rng): Params | null;
  beats: StoryBeat[];
}

export const STORIES: StoryDef[] = [];

export function defineStory(def: StoryDef): void {
  STORIES.push(def);
}

export function storyParams(state: TownState, doc: Document): Params {
  return storyOf(state, doc)?.params ?? doc.payload;
}

export const STD: DocOption[] = [
  { id: "approve", label: "Approve" },
  { id: "deny", label: "Deny" },
  { id: "defer", label: "Defer" },
];
export const AD: DocOption[] = [
  { id: "approve", label: "Approve" },
  { id: "deny", label: "Deny" },
];
export const FILE: DocOption[] = [{ id: "file", label: "File" }];

export function cit(state: TownState, id: unknown): Citizen | null {
  return typeof id === "number" ? (state.citizens[id] ?? null) : null;
}

export function sname(state: TownState, i: number): string {
  return state.streets[i]?.name ?? "Main Street";
}

export function addr(state: TownState, c: Citizen): string {
  return `${((c.id * 7) % 180) + 1} ${sname(state, c.street)}`;
}

export function nm(c: Citizen): string {
  return fullName(c);
}

export function deptName(state: TownState, id: DeptId | null | undefined): string {
  return state.departments.find((d) => d.id === id)?.name ?? "the department";
}

export function pickCitizen(ctx: Ctx, pred: (c: Citizen) => boolean): Citizen | null {
  const pool = ctx.state.citizens.filter((c) => c.present && pred(c));
  return pool.length ? ctx.rng.pick(pool) : null;
}

/** Use the citizen named in params, or choose one and record it. */
export function senderOf(ctx: Ctx, p: Params, pred: (c: Citizen) => boolean = () => true): Citizen | null {
  const given = cit(ctx.state, p.c);
  if (given) return given;
  const c = pickCitizen(ctx, pred);
  if (c) p.c = c.id;
  return c;
}

export function neighbour(ctx: Ctx, c: Citizen): Citizen | null {
  return pickCitizen(ctx, (x) => x.street === c.street && x.id !== c.id);
}

export function mood(c: Citizen, d: number): void {
  c.mood = clamp(c.mood + d, -1, 1);
}

export function trustOf(c: Citizen, d: number): void {
  c.trustOffset = clamp(c.trustOffset + d, -0.5, 0.5);
}

export function role(state: TownState, r: Citizen["role"]): Citizen | null {
  return state.citizens.find((c) => c.role === r && c.present) ?? null;
}

/** The story a document belongs to, if any. */
export function storyOf(state: TownState, doc: Document): Story | null {
  const id = doc.payload.story;
  return typeof id === "string" ? (state.stories.find((s) => s.id === id) ?? null) : null;
}

export function choiceOf(state: TownState, doc: Document, beat: number): string | undefined {
  return storyOf(state, doc)?.choices[beat];
}

/** Move n working staff from the best-staffed other department. Returns the names moved. */
export function moveStaff(state: TownState, to: DeptId, n: number): string[] {
  const moved: string[] = [];
  const others = state.departments.filter((d) => d.id !== to).sort((a, b) => state.services[b.id] - state.services[a.id]);
  for (const from of others) {
    for (const c of state.citizens) {
      if (moved.length >= n) break;
      if (c.dept === from.id && c.present && c.working && c.role === null) {
        c.dept = to;
        moved.push(nm(c));
      }
    }
    if (moved.length >= n) break;
  }
  return moved;
}

/** How strange the town has become: rises with the calendar and with disorder. */
export function absurdity(state: TownState): number {
  return clamp((state.day - 4) / 20) * 0.7 + (1 - state.order) * 0.3;
}

export function createDoc(state: TownState, rng: Rng, template: string, params: Params): Document | null {
  const t = T[template];
  if (!t) throw new Error(`unknown document template: ${template}`);
  if (t.minDay && state.day < t.minDay) return null;
  const last = state.used[template];
  if (t.cooldown && last !== undefined && state.day - last < t.cooldown) return null;
  const count = state.used[`n:${template}`] ?? 0;
  if (count >= (t.maxPerMonth ?? 10)) return null;
  const payload: Params = { ...params };
  const draft = t.make({ state, rng }, payload);
  if (!draft) return null;
  state.used[template] = state.day;
  state.used[`n:${template}`] = count + 1;
  if (draft.sender !== null) state.used[`c:${draft.sender}`] = state.day;
  return {
    id: state.nextDocId++,
    day: state.day,
    kind: draft.kind,
    template,
    sender: draft.sender,
    senderLabel: draft.senderLabel,
    title: draft.title,
    body: draft.body,
    options: draft.options,
    age: 0,
    priority: draft.priority + (typeof payload.story === "string" ? 1 : 0),
    payload,
    status: "pending",
    chosen: null,
    resolvedDay: null,
    outcome: null,
  };
}

/** Create a document for tomorrow's tray from inside a resolution. */
export function queue(ctx: Ctx, template: string, params: Params): void {
  const d = createDoc(ctx.state, ctx.rng, template, params);
  if (d) ctx.state.queued.push(d);
}
