export function clamp(x: number, lo = 0, hi = 1): number {
  return Math.max(lo, Math.min(hi, x));
}

/** Gaussian bump centred on `center`, 1 at the centre, ~0.37 at one `width` away. */
export function bell(x: number, center: number, width: number): number {
  const d = (x - center) / width;
  return Math.exp(-d * d);
}

export function must<T>(v: T | undefined | null, what = "value"): T {
  if (v === undefined || v === null) throw new Error(`missing ${what}`);
  return v;
}

export function fullName(c: { first: string; last: string }): string {
  return `${c.first} ${c.last}`;
}

export function pct(x: number): string {
  return `${Math.round(x * 100)}%`;
}

export function listNames(names: string[]): string {
  if (names.length === 0) return "nobody";
  if (names.length === 1) return names[0] as string;
  if (names.length === 2) return `${names[0]} and ${names[1]}`;
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}

export function ordinal(n: number): string {
  const s = ["th", "st", "nd", "rd"];
  const v = n % 100;
  return `${n}${s[(v - 20) % 10] ?? s[v] ?? s[0]}`;
}
