// One turn of the month: the player's day ends, the town has its day, and tomorrow's in-tray is built.

import type { Rng } from "./rng";
import { applyBulletin, bulletinOptions, checkStatements } from "./bulletin";
import { copingCounts, dominantStyle, presentCount, pressures, bestStyle, streetMix, updateCoping, updateMoods } from "./coping";
import { createDoc, generateDailyDocs, lapseDoc } from "./documents";
import { buildEpilogue } from "./epilogue";
import { event, ledger, paper } from "./log";
import { dueExploits, modifiers } from "./ordinances";
import { DEPT_IDS, type CopingStyle, type Document, type TownState } from "./types";
import { clamp, fullName, listNames } from "./util";

export const TRAY_CAP = 10;

export function computeServices(state: TownState): void {
  for (const dept of state.departments) {
    let s = 0;
    for (const c of state.citizens) {
      if (c.dept !== dept.id || !c.present || !c.working || c.strikeUntil > state.day) continue;
      s += c.homeDept === dept.id ? 1 : 0.7;
    }
    state.services[dept.id] = Math.min(1.25, s / dept.required);
  }
}

function applyOutages(state: TownState, rng: Rng): void {
  for (const kind of ["water", "power"] as const) {
    const s = state.services[kind];
    const n = s >= 0.6 ? 0 : Math.round(((0.6 - s) / 0.6) * (state.streets.length - 1));
    for (const st of state.streets) st[kind] = true;
    const order = rng.shuffle(state.streets.slice(1).map((x) => x.id));
    for (let i = 0; i < n; i++) {
      const st = state.streets[order[i] ?? 0];
      if (st) st[kind] = false;
    }
    if (s < 0.15 && state.streets[0]) state.streets[0][kind] = false;
    const out = state.streets.filter((x) => !x[kind]).map((x) => x.name);
    if (out.length) event(state, `${kind === "water" ? "Water" : "Power"} out on ${listNames(out.slice(0, 4))}${out.length > 4 ? ` and ${out.length - 4} more` : ""}.`);
  }
  const ok = state.streets.filter((x) => x.water && x.power).length / state.streets.length;
  state.uptimeSum += ok;
}

function departures(state: TownState, rng: Rng): void {
  for (const c of state.citizens) {
    if (!c.present) continue;
    if (c.tags.includes("leaving")) {
      c.present = false;
      c.working = false;
      if (c.dept) {
        ledger(state, `${fullName(c)} left town without formally leaving the ${state.departments.find((d) => d.id === c.dept)?.name ?? ""} Department.`, [fullName(c)], 1);
        c.dept = null;
      }
      continue;
    }
    if (c.coping === "flight" && c.dept === null && c.role === null && rng.chance(0.2)) {
      c.present = false;
      c.working = false;
    }
    if (c.strikeUntil > 0 && c.strikeUntil <= state.day && c.dept && !c.working && c.coping !== "quiet" && !c.tags.includes("volunteer")) {
      c.working = true;
      c.strikeUntil = 0;
    }
  }
}

function welfareSweep(state: TownState, rng: Rng): void {
  if (!modifiers(state).welfareChecks) return;
  if ((state.services.police + state.services.parks) / 2 < 0.4) return;
  const mix = streetMix(state);
  const mods = modifiers(state);
  const streets = rng.shuffle(state.streets.map((s) => s.id)).slice(0, 2);
  const names: string[] = [];
  for (const st of streets) {
    for (const c of state.citizens) {
      if (!c.present || c.street !== st || c.coping !== "quiet") continue;
      if (rng.chance(0.3)) {
        c.coping = bestStyle(pressures(state, c, mix, mods), "quiet");
        c.copingSince = state.day;
        c.working = c.dept !== null;
        c.mood = clamp(c.mood + 0.3, -1, 1);
        names.push(fullName(c));
      }
    }
  }
  if (names.length) {
    state.kpis.welfareChecks++;
    ledger(state, `Rolling welfare checks reached ${listNames(names)}, who answered.`, names, 2);
  }
}

function updateCult(state: TownState): void {
  if (!state.cult) return;
  const piety = copingCounts(state).piety;
  state.cult.members = (state.cult.registered ? 5 : 2) + piety * (state.cult.registered ? 3 : 2);
}

function updateTownMeters(state: TownState): void {
  const mods = modifiers(state);
  const n = Math.max(1, presentCount(state));
  const counts = copingCounts(state);
  const rageF = counts.rage / n;
  const hedF = counts.hedonism / n;
  const quietF = counts.quiet / n;
  const outageF = state.streets.filter((s) => !s.water || !s.power).length / state.streets.length;

  let orderTarget = 0.4 * Math.min(1, state.services.police) + 0.3 * (1 - Math.min(1, rageF * 3)) + 0.3 * state.trust;
  if (mods.curfew && state.trust > 0.35) orderTarget += 0.1;
  if (mods.legalizeAll) orderTarget -= 0.1;
  if (mods.holiday) orderTarget -= 0.05;
  if (mods.barsOpen) orderTarget -= 0.08;
  state.order = clamp(state.order + 0.25 * (clamp(orderTarget) - state.order));

  let moraleTarget =
    0.4 +
    0.25 * Math.min(1, hedF * 2) -
    0.5 * Math.min(1, quietF * 3) +
    0.15 * (Math.min(1, state.services.sanitation) - 0.5) +
    0.1 * (Math.min(1, state.services.parks) - 0.5) -
    0.2 * outageF -
    0.25 * clamp((state.day - 20) / 10);
  if (mods.holiday) moraleTarget += 0.05;
  if (mods.barsOpen) moraleTarget += 0.05;
  if (mods.pensionRaided) moraleTarget += 0.08;
  if (mods.curfew) moraleTarget -= 0.08;
  if (mods.schoolsClosed) moraleTarget -= 0.03;
  if (mods.priceControls) moraleTarget += 0.03;
  state.morale = clamp(state.morale + 0.25 * (clamp(moraleTarget, 0, 0.9) - state.morale));

  state.trust = clamp(state.trust + 0.01 * (0.45 - state.trust) - 0.02 * outageF);

  const staff = state.citizens.filter((c) => c.dept && c.present && c.working).length;
  const revenue = 2 + 6 * state.trust * state.order;
  const payroll = mods.payrollFreeze ? 0 : staff * 0.1;
  state.treasury = Math.round((state.treasury + revenue - payroll) * 10) / 10;
}

function officeCheck(state: TownState): void {
  if (!state.office.held || state.day < 10) return;
  state.lowTrustDays = state.trust < 0.15 ? state.lowTrustDays + 1 : 0;
  const council = state.citizens.filter((c) => c.role === "council" && c.present);
  const chief = state.citizens.find((c) => c.role === "chief" && c.present);
  let lostTo: string | null = null;
  let headline = "";
  let body = "";
  if (state.lowTrustDays >= 4 && council.length >= 2) {
    lostTo = "Council";
    headline = "Council Convenes, Removes Acting Town Manager";
    body = `Council met for the first time since the announcement and voted ${council.length} to 0 to remove the Acting Town Manager, citing a loss of public confidence. ${council[0] ? `Councillor ${fullName(council[0])}` : "The chair"} will act until a replacement is found. The stamp has been collected.`;
  } else if (chief && chief.coping === "rage" && !chief.tags.includes("deputy-tm") && state.order < 0.3 && state.trust < 0.35) {
    lostTo = `Chief ${fullName(chief)}`;
    headline = "Police Chief Assumes Municipal Authority 'For the Duration'";
    body = `Chief ${fullName(chief)} entered Town Hall this morning with four officers and a memorandum appointing the Chief as Acting Town Manager. The memorandum was signed by the Chief. The previous Acting Town Manager was escorted to the car park.`;
  } else if (state.cult?.registered && state.cult.members >= 40 && state.trust < 0.4) {
    lostTo = state.cult.name;
    headline = `${state.cult.name} Occupies Town Hall; Services Moved Indoors`;
    body = `Members of ${state.cult.name} entered Town Hall at dusk and have declared it a place of worship under the Town's own registration. The Acting Town Manager's desk has been moved to the bandstand, with the Acting Town Manager.`;
  }
  if (!lostTo) return;
  state.office = { held: false, lostDay: state.day, lostTo };
  state.stampsPerDay = 0;
  ledger(state, `The Acting Town Manager was removed from office by ${lostTo}. The parking pass was returned.`, [], 5);
  paper(state, headline, body, 5);
}

const FILLER: Record<CopingStyle, string[]> = {
  denial: ["Council Agenda Published for Next Quarter", "Library Extends Hours; Fines Still Apply", "Pothole on Main Street Scheduled for Spring"],
  duty: ["Water Plant 'Fine,' Says Engineer, Who Lives There Now", "Bins Collected on Schedule; Residents Puzzled", "Records Department Reports Records in Order"],
  hedonism: ["Third Night of Parties; Residents 'Fine'", "Bandstand Booked Through to the End", "Noise Complaints Up, Complainants Down"],
  piety: ["Vigil Attendance Up; Chairs Requested", "Bandstand Services Add Second Sitting", "Candles Sold Out at Hardware Store; Hardware Store Attending"],
  rage: ["Letters Page Expanded to Four Pages", "Town Hall Phones Ringing; Town Hall Not Answering", "Resident Shouts at Sky; Sky Unmoved"],
  hoarding: ["Supermarket Shelves Bare; Manager Cites 'Enthusiasm'", "Batteries Now a Currency", "Garage Sales Replaced by Garage Purchases"],
  flight: ["Northbound Lanes Busy; Southbound Empty", "Estate Agent Reports 'Interesting Week'", "Bus Timetable Suspended; Buses Also Gone"],
  confession: ["Letters Page Now Entirely Confessions", "Library Reports Record Returns", "Rotary Club Learns Truth About 2009 Float"],
  bargaining: ["Petition Drive Seeks to Rename Town; Second Petition Seeks to Rename Petition", "Resident Offers Object 'Terms'", "Ark Construction Up Sharply"],
  quiet: ["Several Addresses Not Answering; Neighbours Asked to Check In", "Streets Quiet; Paper Delivered Regardless"],
};

function printPaper(state: TownState, rng: Rng): void {
  const today = state.paper.filter((p) => p.day === state.day);
  const dom = dominantStyle(state);
  if (today.length < 2) {
    const recent = new Set(state.paper.filter((p) => p.day >= state.day - 6).map((p) => p.headline));
    const fresh = FILLER[dom].filter((hl) => !recent.has(hl));
    const headline = rng.pick(fresh.length ? fresh : FILLER[dom]);
    const body = dom === "quiet"
      ? `The ${state.paperName} reports, without comment, that several households on ${rng.pick(state.streets).name} have not been seen this week. Neighbours who can are asked to knock.`
      : rng.pick([
          `The ${state.paperName} has been unable to confirm the above and prints it anyway, the editor having "a feeling."`,
          `Details on page two. There is no page two. The ${state.paperName} apologises and will try again tomorrow.`,
          `The ${state.paperName} notes the above and has nothing to add, which the editor describes as a first.`,
          `Residents with further information are asked to contact the ${state.paperName}, which is one person, who is at lunch.`,
        ]);
    paper(state, headline, body, 1);
  }
  if (state.day === 29 && state.flags.includes("prophecy"))
    paper(state, "Bandstand's Revised Date Passes; Date Revised Again", `Day 28, the date to which ${state.cult?.name ?? "the bandstand"} had revised the end, passed without incident. The congregation met anyway, waited, and at midnight announced a further revision, to Day 30, "as originally understood." The trombone played.`, 3);
  if (state.day === 14) paper(state, "Editorial: We Appear to Be Going Through Stages", `This paper has noticed, over two weeks, a pattern in the town's conduct that readers with a psychology textbook will recognise. We decline to name it. We note only that we appear to be on schedule, and that the editor would like to skip one.`, 3);
}

function assembleTray(state: TownState, rng: Rng, carried: Document[], fresh: Document[]): Document[] {
  if (state.day === 30) {
    const final = createDoc(state, rng, "final", {});
    return final ? [final] : [];
  }
  const pool = [...state.queued, ...fresh];
  rng.shuffle(pool);
  pool.sort((a, b) => b.priority - a.priority);
  const room = Math.max(0, TRAY_CAP - carried.length);
  const counts: Record<string, number> = {};
  const chosen: Document[] = [];
  for (const d of pool) {
    if (chosen.length >= room) break;
    const cap = d.template === "permit.routine" ? 3 : 2;
    const n = counts[d.template] ?? 0;
    if (n >= cap) continue;
    counts[d.template] = n + 1;
    chosen.push(d);
  }
  for (const d of chosen) d.day = state.day;
  return [...carried, ...chosen];
}

export function endDay(state: TownState, rng: Rng): void {
  if (state.ended) return;
  state.events = [];
  applyBulletin(state, rng, state.bulletinToday);

  const carried: Document[] = [];
  for (const d of state.inTray) {
    if (d.status !== "pending") {
      state.archive.push(d);
      continue;
    }
    if (d.chosen === "defer") {
      d.chosen = null;
      if (d.age >= 2) {
        lapseDoc(state, rng, d);
        d.outcome = `Deferred twice; the applicant stopped waiting. ${d.outcome ?? ""}`.trim();
        state.archive.push(d);
      } else carried.push(d);
      continue;
    }
    lapseDoc(state, rng, d);
    state.archive.push(d);
  }
  state.inTray = [];

  for (const req of dueExploits(state, rng)) {
    const d = createDoc(state, rng, req.template, req.params);
    if (d) state.queued.push(d);
  }

  welfareSweep(state, rng);
  departures(state, rng);
  const mods = modifiers(state);
  updateMoods(state, rng, mods);
  const switched = updateCoping(state, rng, mods);
  const toQuiet = switched.filter((s) => s.to === "quiet").length;
  if (toQuiet > 0) event(state, `${toQuiet} resident${toQuiet === 1 ? "" : "s"} stopped answering the door.`);
  updateCult(state);
  computeServices(state);
  applyOutages(state, rng);
  updateTownMeters(state);
  checkStatements(state);
  officeCheck(state);

  const fresh = generateDailyDocs(state, rng);
  printPaper(state, rng);

  state.day++;
  if (state.day > 30) {
    state.ended = true;
    state.inTray = [];
    state.queued = [];
    state.bulletinOptions = [];
    state.bulletinToday = null;
    state.epilogue = buildEpilogue(state);
    return;
  }

  state.inTray = assembleTray(state, rng, carried, fresh);
  state.queued = [];

  const mods2 = modifiers(state);
  const holidayOrd = state.ordinances.find((o) => o.id === "holiday" && o.active);
  const holidayToday = (holidayOrd && (state.day - holidayOrd.signedDay) % 7 === 0 && state.day > holidayOrd.signedDay) || state.flags.includes("everyday");
  state.stampsPerDay = state.office.held ? Math.round(4 + 4 * Math.min(1, state.services.records)) : 0;
  if (holidayToday && state.office.held) {
    const everyday = state.flags.includes("everyday");
    state.stampsPerDay = everyday ? 2 : 0;
    event(state, everyday ? "Every day is a holiday. You came in anyway. Two stamps, quietly." : "Municipal holiday. No stamps today, by ordinance.");
  }
  if (state.day === 28 && state.flags.includes("closed-28") && state.office.held) {
    state.stampsPerDay = 0;
    event(state, `The Town is closed today, at the request of ${state.cult?.name ?? "the bandstand"}. The desk came in anyway.`);
  }
  state.stampsLeft = state.stampsPerDay;
  state.bulletinToday = null;
  state.bulletinOptions = bulletinOptions(state, mods2);
  for (const id of DEPT_IDS) if (state.services[id] < 0.5) event(state, `${state.departments.find((d) => d.id === id)?.name ?? id} below half strength.`);
}
