// The application shell: screens, actions, saving, keyboard.

import { ActionError, applyAction, newGame } from "../sim/game";
import type { Action, DeptId, TownState } from "../sim/types";
import * as audio from "./audio";
import { renderBriefing, renderDocument, renderInTray, renderWall, type DeskCallbacks } from "./desk";
import { h } from "./dom";
import { renderEpilogue, renderEvening, renderTitle } from "./overlays";
import { clearSave, loadGame, saveGame } from "./save";

type Screen = "title" | "desk" | "evening" | "epilogue";

export class App {
  private state: TownState | null = null;
  private screen: Screen = "title";
  private selected: number | null = null;
  private toastEl: HTMLElement | null = null;
  private buildStamp = "local";

  constructor(private root: HTMLElement) {}

  boot(): void {
    fetch(`${import.meta.env.BASE_URL}build.txt`)
      .then((r) => (r.ok ? r.text() : "local"))
      .then((t) => {
        const s = t.trim();
        // The dev server answers unknown paths with the page itself; only a short stamp counts.
        this.buildStamp = s.length < 60 && !s.startsWith("<") ? s : "local";
        this.render();
      })
      .catch(() => {});
    document.addEventListener("keydown", (e) => this.onKey(e));
    this.devFastForward();
    this.render();
  }

  /** Development aid: ?seed=N&ff=D starts a town and plays D days with the first option on everything. */
  private devFastForward(): void {
    const q = new URLSearchParams(window.location.search);
    const ff = Number(q.get("ff"));
    if (!q.has("ff") || !Number.isFinite(ff)) return;
    const seed = Number(q.get("seed") ?? 1);
    this.state = newGame(Number.isFinite(seed) ? seed : 1);
    for (let i = 0; i < ff && !this.state.ended; i++) {
      for (const doc of [...this.state.inTray]) {
        if (this.state.stampsLeft <= 0 || doc.status !== "pending" || doc.chosen === "defer") continue;
        let option = doc.options[0]?.id ?? "file";
        if (doc.template === "story.mayor.petition" || doc.template === "petition.recall") option = "deny";
        if (doc.template === "story.mayor.return") option = "refuse";
        applyAction(this.state, { type: "stamp", docId: doc.id, option });
      }
      if (this.state.bulletinOptions.some((o) => o.id === "plan")) applyAction(this.state, { type: "bulletin", id: "plan" });
      applyAction(this.state, { type: "endDay" });
    }
    this.screen = this.state.ended ? "epilogue" : "desk";
    saveGame(this.state);
  }

  private begin(seed: number): void {
    this.state = newGame(seed);
    this.selected = null;
    this.screen = "desk";
    saveGame(this.state);
    audio.hum(true);
    this.render();
  }

  private continueSaved(): void {
    const s = loadGame();
    if (!s) return;
    this.state = s;
    this.selected = null;
    this.screen = s.ended ? "epilogue" : "desk";
    audio.hum(true);
    this.render();
  }

  private dispatch(action: Action): boolean {
    if (!this.state) return false;
    try {
      applyAction(this.state, action);
    } catch (e) {
      this.toast(e instanceof ActionError ? e.message : "That did not go through.");
      return false;
    }
    saveGame(this.state);
    return true;
  }

  private callbacks(): DeskCallbacks {
    return {
      select: (id) => {
        this.selected = id;
        audio.slide();
        this.render();
      },
      stamp: (docId, option) => {
        if (this.dispatch({ type: "stamp", docId, option })) audio.stamp();
        this.render();
      },
      bulletin: (id) => {
        this.dispatch({ type: "bulletin", id });
      },
      reassign: (citizenId, dept: DeptId) => {
        this.dispatch({ type: "reassign", citizenId, dept });
        this.render();
      },
      endDay: () => this.endDay(),
    };
  }

  private endDay(): void {
    if (!this.state || this.screen !== "desk") return;
    if (!this.dispatch({ type: "endDay" })) return;
    this.selected = null;
    this.screen = "evening";
    audio.printer();
    this.render();
    window.scrollTo(0, 0);
  }

  private nextMorning(): void {
    if (!this.state) return;
    this.screen = this.state.ended ? "epilogue" : "desk";
    if (this.state.ended) audio.hum(false);
    this.render();
    window.scrollTo(0, 0);
  }

  private newTown(): void {
    clearSave();
    this.state = null;
    this.screen = "title";
    this.render();
  }

  private onKey(e: KeyboardEvent): void {
    if (!this.state) return;
    const target = e.target as HTMLElement | null;
    if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA")) return;
    if (this.screen === "desk") {
      const doc = this.selected !== null ? this.state.inTray.find((d) => d.id === this.selected) : undefined;
      const idx = ["1", "2", "3", "4"].indexOf(e.key);
      if (doc && idx >= 0 && doc.options[idx] && doc.status === "pending" && doc.chosen !== "defer") {
        this.callbacks().stamp(doc.id, doc.options[idx]!.id);
        return;
      }
      if (e.key === "e" || e.key === "E") this.endDay();
      if (e.key === "ArrowDown" || e.key === "ArrowUp" || e.key === "j" || e.key === "k") {
        const pending = this.state.inTray.filter((d) => d.status === "pending" && d.chosen !== "defer");
        if (pending.length === 0) return;
        const i = pending.findIndex((d) => d.id === this.selected);
        const next = e.key === "ArrowDown" || e.key === "j" ? Math.min(pending.length - 1, i + 1) : Math.max(0, i - 1);
        this.callbacks().select(pending[next]?.id ?? null);
        e.preventDefault();
      }
    } else if (this.screen === "evening" && (e.key === "Enter" || e.key === " " || e.key === "e" || e.key === "E")) {
      this.nextMorning();
    }
  }

  private toast(text: string): void {
    if (!this.toastEl) return;
    this.toastEl.textContent = text;
    this.toastEl.classList.add("show");
    setTimeout(() => this.toastEl?.classList.remove("show"), 1800);
  }

  render(): void {
    const s = this.state;
    let screen: HTMLElement;
    if (!s || this.screen === "title") {
      screen = renderTitle(loadGame() !== null, (seed) => this.begin(seed), () => this.continueSaved());
    } else if (this.screen === "evening") {
      screen = renderEvening(s, () => this.nextMorning());
    } else if (this.screen === "epilogue") {
      screen = renderEpilogue(s, () => this.newTown());
    } else {
      const cb = this.callbacks();
      const doc = this.selected !== null ? s.inTray.find((d) => d.id === this.selected) : undefined;
      screen = h(
        "section",
        { class: "desk" },
        h(
          "header",
          { class: "desk-head" },
          h("span", { class: "town" }, `Town of ${s.townName}`),
          h("span", { class: "office" }, "Office of the Town Manager (Acting)"),
          h("span", { class: "day" }, `Day ${s.day} of 30`),
        ),
        renderInTray(s, this.selected, cb),
        h("main", { class: "blotter" }, doc ? renderDocument(s, doc, cb) : renderBriefing(s)),
        renderWall(s, cb),
      );
    }
    this.toastEl = h("div", { class: "toast" });
    const foot = h(
      "footer",
      { class: "foot" },
      h("span", {}, `build ${this.buildStamp}`),
      s ? h("span", {}, `seed ${s.seed}`) : null,
      h("button", { class: "link", type: "button", onclick: () => { audio.setMuted(!audio.isMuted()); if (!audio.isMuted() && this.screen === "desk") audio.hum(true); this.render(); } }, audio.isMuted() ? "Sound off" : "Sound on"),
      s && this.screen !== "title" ? h("button", { class: "link", type: "button", onclick: () => { if (confirm("Leave this town and start another? The month will not be saved.")) this.newTown(); } }, "Abandon town") : null,
    );
    this.root.replaceChildren(screen, foot, this.toastEl);
  }
}
