import { deserialize, serialize } from "../sim/game";
import type { TownState } from "../sim/types";

const KEY = "bau.save.v2";

export function saveGame(state: TownState): void {
  try {
    localStorage.setItem(KEY, serialize(state));
  } catch {
    // Private mode or storage full: the month continues unsaved.
  }
}

export function loadGame(): TownState | null {
  try {
    const text = localStorage.getItem(KEY);
    return text ? deserialize(text) : null;
  } catch {
    return null;
  }
}

export function clearSave(): void {
  try {
    localStorage.removeItem(KEY);
  } catch {
    // nothing to clear
  }
}
