define("charter", {
  make: (ctx) => ({
    kind: "memo",
    title: "RE: Continuity of Municipal Operations",
    body: `Per Section 4.2(c) of the Town Charter, in the absence of the Town Manager (resigned), the Deputy Town Manager (resigned), the Mayor (with family), and the Clerk (last seen leaving with the office plant), the Deputy Clerk shall perform the duties of the Town Manager until such time as Council confirms a replacement.\n\nCouncil has been notified. Council has not responded.\n\nThe stamp is in the top drawer. The object is in the sky. The ${ctx.state.paperName} has called twice.`,
    options: FILE,
    sender: null,
    senderLabel: "Office of the Town Clerk (vacant)",
    priority: 9,
  }),
  resolve: () => "Filed. The stamp was in the top drawer.",
});

define("final", {
  make: () => ({
    kind: "memo",
    title: "Notice of Termination of Municipal Operations",
    body: `Per Section 12 of the Town Charter ("Dissolution"), municipal operations terminate at the close of business today.\n\nThe Acting Town Manager is asked to sign below to confirm that all documents have been processed, all stamps returned, and all lights switched off on leaving.\n\nThe Charter does not say what happens if the Acting Town Manager declines to sign. The Charter was not written with today in mind.`,
    options: [
      { id: "sign", label: "Sign" },
      { id: "decline", label: "Decline to sign" },
    ],
    sender: null,
    senderLabel: "The Town Charter",
    priority: 10,
  }),
  resolve: (ctx, _doc, option) => {
    if (option === "sign") {
      ledger(ctx.state, "The Acting Town Manager signed the Notice of Termination. All stamps were returned. The lights were switched off on leaving.", [], 4);
      return "Signed. The stamp is back in the top drawer.";
    }
    ledger(ctx.state, "The Acting Town Manager declined to sign the Notice of Termination. Operations terminated regardless.", [], 4);
    return "Declined. Operations terminated regardless.";
  },
  lapse: (ctx) => {
    ledger(ctx.state, "The Notice of Termination was left on the desk, unsigned. Operations terminated regardless.", [], 4);
    return "Left on the desk.";
  },
});

