define("permit.routine", {
  maxPerMonth: 40,
  make: (ctx, p) => {
    const c = senderOf(ctx, p);
    if (!c) return null;
    let v = ctx.rng.int(0, ROUTINE.length - 1);
    for (let guard = 0; guard < 10 && ctx.state.day - (ctx.state.used[`rv:${v}`] ?? -9) < 4; guard++) v = ctx.rng.int(0, ROUTINE.length - 1);
    ctx.state.used[`rv:${v}`] = ctx.state.day;
    const r = ROUTINE[v] as (typeof ROUTINE)[number];
    p.thing = r.thing;
    return { kind: "permit", title: r.title, body: r.body(nm(c), addr(ctx.state, c)), options: STD, sender: c.id, senderLabel: nm(c), priority: 2 };
  },
  resolve: (ctx, doc, option) => {
    const c = cit(ctx.state, doc.sender);
    if (!c) return "Filed.";
    const thing = String(doc.payload.thing ?? "it");
    if (option === "approve") {
      mood(c, 0.1);
      trustOf(c, 0.05);
      pulse(ctx.state, c.street, "denial", 0.1);
      return `Approved. ${nm(c)} proceeds with ${thing} at once, and tells the street that the system works.`;
    }
    mood(c, -0.2);
    trustOf(c, -0.1);
    pulse(ctx.state, c.street, "rage", 0.1);
    return `Denied. ${nm(c)} will be writing to someone about this.`;
  },
  lapse: (ctx, doc) => {
    const c = cit(ctx.state, doc.sender);
    const thing = String(doc.payload.thing ?? "it");
    const builds = ["a deck", "a fence", "a pool", "a garage sale"].includes(thing);
    if (c && builds && ctx.rng.chance(0.3)) paper(ctx.state, `Resident Proceeds Without Permit; Permit "Pending"`, `${nm(c)} began work on ${thing} at ${addr(ctx.state, c)} yesterday with the application still on the Town Manager's desk. Asked about the permit, ${c.first} said "sure."`, 1);
    return c ? (builds ? `${nm(c)} went ahead with ${thing} anyway. Nobody came.` : `${nm(c)} did not hear back, and has written again, to the same desk.`) : "Unprocessed.";
  },
});

define("complaint.lawn", {
  cooldown: 2,
  maxPerMonth: 6,
  make: (ctx, p) => {
    const c = senderOf(ctx, p);
    if (!c) return null;
    const other = neighbour(ctx, c);
    if (!other) return null;
    p.other = other.id;
    return {
      kind: "complaint",
      title: `Complaint: Unmowed Lawn, ${addr(ctx.state, other)}`,
      body: `${nm(c)} wishes to report that the lawn at ${addr(ctx.state, other)} has not been mowed in nine days and is now, in the complainant's estimation, a meadow. ${c.first} notes that standards are standards, and that this is written on a plaque in the Records Department, and that ${c.first} has seen the plaque.`,
      options: [
        { id: "cite", label: "Issue citation" },
        { id: "dismiss", label: "Dismiss" },
      ],
      sender: c.id,
      senderLabel: nm(c),
      priority: 2,
    };
  },
  resolve: (ctx, doc, option) => {
    const c = cit(ctx.state, doc.sender);
    const other = cit(ctx.state, doc.payload.other);
    if (!c || !other) return "Filed.";
    if (option === "cite") {
      mood(other, -0.15);
      pulse(ctx.state, other.street, "rage", 0.05);
      mood(c, 0.1);
      ctx.state.order = clamp(ctx.state.order + 0.01);
      ledger(ctx.state, `${nm(other)} was cited for an unmowed lawn on the complaint of ${nm(c)}. The lawn was not mowed.`, [nm(other), nm(c)], 1);
      return `Citation issued to ${nm(other)}. The lawn remains a meadow.`;
    }
    mood(c, -0.1);
    trustOf(c, -0.05);
    return `Dismissed. ${nm(c)} has photographed the plaque.`;
  },
});

