define("request.overtime", {
  maxPerMonth: 5,
  make: (ctx, p) => {
    const c = senderOf(ctx, p, (x) => x.dept !== null && x.working && x.coping === "duty");
    if (!c || !c.dept) return null;
    const d = deptName(ctx.state, c.dept);
    return {
      kind: "staffing",
      title: `Request: Overtime Authorisation, ${d}`,
      body: `${nm(c)} requests authorisation for overtime in the ${d} Department for the remainder of the month. Hours requested: all of them. ${c.first} notes that the overtime rate is time and a half and that time is the issue.`,
      options: AD,
      sender: c.id,
      senderLabel: `${nm(c)}, ${d}`,
      priority: 3,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    if (option === "approve") {
      s.treasury -= 4;
      mood(c, 0.1);
      if (c.dept) pulse(s, c.street, "duty", 0.1);
      return `Approved. ${c.first} has not gone home.`;
    }
    mood(c, -0.1);
    return `Denied. ${c.first} has not gone home either, and is not being paid for it.`;
  },
});

