define("welfare.check", {
  cooldown: 1,
  maxPerMonth: 30,
  make: (ctx, p) => {
    const s = ctx.state;
    const quietByStreet = s.streets.map((st) => s.citizens.filter((c) => c.present && c.street === st.id && c.coping === "quiet").length);
    const candidates = s.streets.filter((st) => (quietByStreet[st.id] ?? 0) >= 2);
    if (candidates.length === 0) return null;
    const st = ctx.rng.pick(candidates);
    const c = senderOf(ctx, p, (x) => x.street === st.id && x.coping !== "quiet");
    if (!c) return null;
    p.street = st.id;
    const n = quietByStreet[st.id] ?? 0;
    return {
      kind: "staffing",
      title: `Request for Welfare Check: ${st.name}`,
      body: `${nm(c)} reports that the curtains at ${n} addresses on ${st.name} have not moved in several days and that post is accumulating. ${c.first} has knocked. ${c.first} would like someone with a uniform to knock.`,
      options: AD,
      sender: c.id,
      senderLabel: nm(c),
      priority: 4,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const st = Number(doc.payload.street ?? 0);
    const c = cit(s, doc.sender);
    if (option !== "approve") return "Denied. The curtains did not move.";
    const capacity = (s.services.police + s.services.parks) / 2;
    if (capacity < 0.25) return "Approved, but nobody was available to go. The request has been placed on the desk, near the top.";
    s.kpis.welfareChecks++;
    const quiet = s.citizens.filter((x) => x.present && x.street === st && x.coping === "quiet");
    const answered: string[] = [];
    const not: string[] = [];
    const mix = streetMix(s);
    const mods = modifiers(s);
    for (const q of quiet) {
      if (ctx.rng.chance(0.5)) {
        const pr = pressures(s, q, mix, mods);
        q.coping = bestStyle(pr, "quiet");
        q.copingSince = s.day;
        q.working = q.dept !== null;
        mood(q, 0.3);
        answered.push(nm(q));
      } else not.push(nm(q));
    }
    ledger(s, `A welfare check on ${sname(s, st)}${c ? `, requested by ${nm(c)},` : ""} found ${answered.length ? `${listNames(answered)} at home and willing to talk` : "no one willing to answer"}.${not.length ? ` ${listNames(not)} did not come to the door.` : ""}`, [...answered, ...not], 2);
    return answered.length ? `${listNames(answered)} answered the door.${not.length ? ` ${listNames(not)} did not.` : ""}` : `Nobody answered. The officer left a card.`;
  },
});

define("staffing.request", {
  cooldown: 1,
  maxPerMonth: 20,
  make: (ctx, p) => {
    const s = ctx.state;
    const weak = s.departments.filter((d) => s.services[d.id] < 0.7);
    if (weak.length === 0) return null;
    const dept = ctx.rng.pick(weak);
    const c = senderOf(ctx, p, (x) => x.dept === dept.id && x.working && x.coping === "duty");
    if (!c) return null;
    p.dept = dept.id;
    const pctStr = Math.round(s.services[dept.id] * 100);
    return {
      kind: "staffing",
      title: `Staffing Request: ${dept.name} Department`,
      body: `The ${dept.name} Department is operating at ${pctStr}% of established strength. ${nm(c)} requests the reassignment of two staff from any department that still has them. ${c.first} notes that the work "does not care about the asteroid" and "neither do I, professionally."`,
      options: AD,
      sender: c.id,
      senderLabel: `${nm(c)}, ${dept.name} Department`,
      priority: 4,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const dept = doc.payload.dept as DeptId;
    const dname = deptName(s, dept);
    if (option !== "approve") return `Denied. The ${dname} Department has noted the date.`;
    const moved = moveStaff(s, dept, 2);
    if (moved.length === 0) return `Approved, but no department had anyone to spare. The approval has been framed.`;
    ledger(s, `${listNames(moved)} were reassigned to the ${dname} Department.`, moved, 1);
    return `Approved. ${listNames(moved)} report to ${dname} tomorrow, having been told where it is.`;
  },
});

define("ordinance.proposal", {
  maxPerMonth: 14,
  make: (ctx, p) => {
    const s = ctx.state;
    let ord = p.ord as OrdinanceId | undefined;
    const c = cit(s, p.c);
    if (!ord) {
      const agenda = c?.agenda ?? "order";
      const pool = ORDINANCE_IDS.filter((id) => ORDINANCES[id].agenda === agenda && !isActive(s, id) && s.day - (s.used[`prop:${id}`] ?? -99) >= 5);
      if (pool.length === 0) return null;
      ord = ctx.rng.pick(pool);
      p.ord = ord;
    }
    if (isActive(s, ord)) return null;
    s.used[`prop:${ord}`] = s.day;
    const def = ORDINANCES[ord];
    const who = p.chief ? role(s, "chief") : c;
    const label = who ? (who.role === "council" ? `Councillor ${nm(who)}` : who.role === "chief" ? `Chief ${nm(who)}` : nm(who)) : "the Records Department";
    const note =
      who?.role === "chief"
        ? "The Chief notes that the Chief's officers are tired and that this is, at bottom, a numbers problem."
        : who?.agenda === "order"
          ? "The proposer notes that order is what we have instead of a plan."
          : who?.agenda === "party"
            ? "The proposer notes that nobody has ever regretted a party, and that the record on that is now closed."
            : who?.agenda === "legacy"
              ? "The proposer asks that the ordinance bear the proposer's name, for the record, which the proposer would like kept somewhere high."
              : "The proposer is a municipal employee and would like it noted that this proposal was made on the proposer's own time.";
    return {
      kind: "ordinance",
      title: `Proposed Ordinance: ${def.name}`,
      body: `${def.proposal}\n\n${note}`,
      options: [
        { id: "approve", label: "Sign" },
        { id: "deny", label: "Decline" },
        { id: "defer", label: "Defer" },
      ],
      sender: who?.id ?? null,
      senderLabel: label,
      priority: who?.role === "chief" ? 6 : 5,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const ord = doc.payload.ord as OrdinanceId;
    const c = cit(s, doc.sender);
    if (option === "approve") {
      signOrdinance(s, ctx.rng, ord, doc.senderLabel);
      if (c) {
        mood(c, 0.2);
        trustOf(c, 0.1);
      }
      return `Signed. ${ORDINANCES[ord].name} is in force. The exceptions will present themselves.`;
    }
    if (c) {
      mood(c, -0.2);
      trustOf(c, c.role === "council" ? -0.15 : -0.05);
    }
    return `Declined. ${doc.senderLabel} has noted the date, and the tone.`;
  },
});

// ---------- Hedonism ----------

define("permit.blockParty", {
  maxPerMonth: 14,
  make: (ctx, p) => {
    const c = senderOf(ctx, p);
    if (!c) return null;
    return {
      kind: "permit",
      title: `Block Party Permit: ${sname(ctx.state, c.street)}, Tonight Until Whenever`,
      body: `The residents of ${sname(ctx.state, c.street)}, represented by ${nm(c)}, request closure of the street to vehicles from 6 p.m. until, per the application, "whenever." Anticipated attendance: everyone. The section of the form on noise mitigation has been left blank, then filled in with a drawing.`,
      options: STD,
      sender: c.id,
      senderLabel: nm(c),
      priority: 3,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    const st = c.street;
    if (option === "approve") {
      pulse(s, st, "hedonism", 0.25);
      pulse(s, (st + 1) % s.streets.length, "hedonism", 0.1);
      pulse(s, (st + s.streets.length - 1) % s.streets.length, "hedonism", 0.1);
      s.morale = clamp(s.morale + 0.02);
      mood(c, 0.2);
      queue(ctx, "complaint.noise", { street: st, party: true });
      paper(s, `${sname(s, st)} Closed to Traffic, Open to Everything Else`, `A permitted block party on ${sname(s, st)} ran until, in the words of the permit, whenever. Neighbouring streets attended. The Sanitation Department attended the following morning.`, 2);
      return `Approved. ${sname(s, st)} is closed to traffic from six. The drawing has been filed.`;
    }
    if (s.order > 0.5) {
      pulse(s, st, "rage", 0.2);
      mood(c, -0.2);
      return `Denied. ${nm(c)} has taken it badly and taken it to the street.`;
    }
    pulse(s, st, "hedonism", 0.3);
    s.trust = clamp(s.trust - 0.03);
    paper(s, `Unpermitted Party on ${sname(s, st)}; Permit Office "Aware"`, `Residents of ${sname(s, st)} held a street party last night despite a denied permit. The Town Manager's office said it was aware. It was difficult not to be.`, 2);
    return `Denied. The party went ahead. The Town was described as "aware."`;
  },
  lapse: (ctx, doc) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (c) pulse(s, c.street, "hedonism", 0.3);
    return "The party happened. The form did not.";
  },
});

