define("strike", {
  cooldown: 4,
  maxPerMonth: 4,
  make: (ctx, p) => {
    const s = ctx.state;
    const byDept = new Map<DeptId, Citizen[]>();
    for (const c of s.citizens) {
      if (c.dept && c.present && c.coping === "rage" && c.strikeUntil <= s.day) {
        const arr = byDept.get(c.dept) ?? [];
        arr.push(c);
        byDept.set(c.dept, arr);
      }
    }
    const entries = [...byDept.entries()].filter(([, v]) => v.length >= 3);
    const picked = entries.length ? ctx.rng.pick(entries) : null;
    if (!picked) return null;
    const [dept, staff] = picked;
    const lead = staff[0] as Citizen;
    p.c = lead.id;
    p.dept = dept;
    p.n = staff.length;
    const dname = deptName(s, dept);
    return {
      kind: "staffing",
      title: `Notice of Industrial Action: ${dname} Department`,
      body: `The undersigned ${staff.length} staff of the ${dname} Department give notice of a work stoppage beginning tomorrow, in protest of conditions, pay, the asteroid, and the vending machine. Demands attached. The vending machine is listed first.`,
      options: [
        { id: "negotiate", label: "Negotiate" },
        { id: "refuse", label: "Refuse" },
      ],
      sender: lead.id,
      senderLabel: `${nm(lead)} and ${staff.length - 1} others, ${dname}`,
      priority: 5,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const dept = doc.payload.dept as DeptId;
    const dname = deptName(s, dept);
    const staff = s.citizens.filter((c) => c.dept === dept && c.present && c.coping === "rage");
    if (option === "negotiate") {
      s.treasury -= 10;
      for (const c of staff) {
        c.coping = "duty";
        c.copingSince = s.day;
        mood(c, 0.1);
      }
      queue(ctx, "invoice.vending", { dept });
      ledger(s, `The ${dname} Department's strike was settled. The vending machine was restocked.`, staff.map(nm), 2);
      return `Settled. The vending machine has been restocked. The ${dname} Department is back, for now.`;
    }
    for (const c of staff) {
      c.strikeUntil = s.day + 3;
      c.working = false;
    }
    paper(s, `${dname} Department Walks Out`, `${staff.length} staff of the ${dname} Department began a work stoppage this morning after the Town refused to negotiate. Picket signs reference the vending machine. The vending machine is also on strike.`, 3);
    ledger(s, `The ${dname} Department struck for three days after the Town refused to negotiate.`, staff.map(nm), 2);
    return `Refused. The ${dname} Department is out for three days.`;
  },
  lapse: (ctx, doc) => {
    const s = ctx.state;
    const dept = doc.payload.dept as DeptId;
    const staff = s.citizens.filter((c) => c.dept === dept && c.present && c.coping === "rage");
    for (const c of staff) {
      c.strikeUntil = s.day + 3;
      c.working = false;
    }
    return `Unanswered. The ${deptName(s, dept)} Department took that as a no, and is out for three days.`;
  },
});

