define("resignation", {
  maxPerMonth: 30,
  make: (ctx, p) => {
    const c = senderOf(ctx, p, (x) => x.dept !== null && x.coping === "flight" && !x.tags.includes("resigning"));
    if (!c || !c.dept) return null;
    c.tags.push("resigning");
    const dname = deptName(ctx.state, c.dept);
    const years = Math.max(1, Math.min(40, c.age - 22));
    const body = ctx.rng.pick([
      `I am writing to tender my resignation from the ${dname} Department, effective immediately. I have given this Town ${years} years and I would like the last month for myself. The keys are on the desk.`,
      `Please accept this letter as notice of my resignation. I wish the ${dname} Department well. I have taken the good stapler, and I would like that to be understood as a choice rather than an oversight.`,
      `I resign. I am sorry to do it by letter but the alternative was to do it in person, and I have been doing things in person for ${years} years. My locker has nothing in it that anyone needs.`,
      `This is my resignation. My sister has a place by the coast and has asked me to come, and I have said yes, and I am writing this at the kitchen table with the car running. I was good at this job. Please tell someone.`,
    ]);
    return {
      kind: "resignation",
      title: `Letter of Resignation: ${nm(c)}, ${dname}`,
      body,
      options: [
        { id: "accept", label: "Accept" },
        { id: "deny", label: "Deny" },
        { id: "defer", label: "Defer" },
      ],
      sender: c.id,
      senderLabel: `${nm(c)}, ${dname} Department`,
      priority: c.role ? 6 : 4,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    const dname = deptName(s, c.dept);
    if (option === "accept") {
      c.dept = null;
      c.working = false;
      c.present = false;
      c.tags.push("resigned");
      ledger(s, `${nm(c)} resigned from the ${dname} Department and left town. The keys were on the desk.`, [nm(c)], c.role ? 3 : 2);
      return `Accepted. ${nm(c)} has gone. The keys were on the desk.`;
    }
    if (ctx.rng.chance(0.3)) {
      c.coping = "duty";
      c.copingSince = s.day;
      c.tags.push("retained");
      mood(c, 0.1);
      ledger(s, `${nm(c)}'s resignation from the ${dname} Department was denied. ${c.first} stayed, out of guilt, mostly.`, [nm(c)], 2);
      return `Denied. ${nm(c)} stayed. Out of guilt, mostly. The stapler has been returned.`;
    }
    c.tags.push("leaving");
    ledger(s, `${nm(c)}'s resignation from the ${dname} Department was denied. ${c.first} left anyway.`, [nm(c)], 2);
    return `Denied. ${nm(c)} left anyway. The denial is on file.`;
  },
  lapse: (ctx, doc) => {
    const c = cit(ctx.state, doc.sender);
    if (c) c.tags.push("leaving");
    return c ? `${nm(c)} left without waiting for a reply.` : "Unprocessed.";
  },
});

