// ---------- Confession ----------

define("confession", {
  maxPerMonth: 10,
  make: (ctx, p) => {
    const c = senderOf(ctx, p, (x) => x.coping === "confession" && !x.tags.includes("confessed") && x.role !== "actuary");
    if (!c) return null;
    c.tags.push("confessed");
    const v = ctx.rng.int(0, 4);
    p.v = v;
    const bodies = [
      `In 1994 I borrowed "The Joy of Cooking" from the branch library and did not return it. I have thought about it every day. I enclose the book. It has been useful.`,
      `At the 2009 Harvest Parade the float belonging to the Rotary Club did not catch fire by accident. I would like this on the record, and I would like the record kept.`,
      `For some years I have been the one moving the "Welcome to ${ctx.state.originalName}" sign four inches to the left every spring. I do not know why I started. I know why I continued.`,
      `I have never liked this town. I have lived here fifty-one years and sat on two committees and I have never once liked it, and I would like that known before it is too late to be disliked back.`,
      `I am the person who has been calling the Town Hall switchboard at 3 a.m. and hanging up. I started in March. I wanted someone to be there. Someone always was. Thank you.`,
    ];
    return {
      kind: "confession",
      title: `Confession: ${nm(c)}`,
      body: bodies[v] ?? bodies[0]!,
      options: [
        { id: "prosecute", label: "Prosecute" },
        { id: "pardon", label: "Pardon" },
        { id: "file", label: "File" },
      ],
      sender: c.id,
      senderLabel: nm(c),
      priority: 2,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    if (option === "prosecute") {
      s.order = clamp(s.order + 0.02);
      mood(c, -0.2);
      ledger(s, `${nm(c)} was prosecuted on ${c.first}'s own confession. The hearing is set for next month.`, [nm(c)], 2);
      return `Prosecuted. A hearing has been set for the fifteenth of next month. ${c.first} has asked whether to bring the book.`;
    }
    if (option === "pardon") {
      trustOf(c, 0.2);
      mood(c, 0.2);
      pulse(s, c.street, "confession", 0.2);
      ledger(s, `${nm(c)} was pardoned. The street heard, and several neighbours began drafting.`, [nm(c)], 2);
      return `Pardoned. ${c.first} wept, briefly, in the Records Department, which has a policy on that.`;
    }
    return `Filed. ${c.first} has asked whether it will be read. It has been read.`;
  },
});

