define("permit.ark", {
  cooldown: 5,
  maxPerMonth: 2,
  make: (ctx, p) => {
    const c = senderOf(ctx, p, (x) => !x.tags.includes("ark"));
    if (!c) return null;
    const miles = ctx.rng.int(40, 300);
    p.miles = miles;
    return {
      kind: "permit",
      title: `Building Permit Application: Vessel, ${addr(ctx.state, c)}`,
      body: `${nm(c)} requests a permit to construct a forty-foot vessel in the driveway at ${addr(ctx.state, c)}, of timber, with a roof, for the carriage of two of each of certain things. The applicant acknowledges that the property is ${miles} miles from navigable water and describes this as "the point."`,
      options: STD,
      sender: c.id,
      senderLabel: nm(c),
      priority: 3,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    const build = () => {
      c.tags.push("ark");
      pulse(s, c.street, "bargaining", 0.2);
      queue(ctx, "complaint.ark", { street: c.street, owner: c.id });
    };
    if (option === "approve") {
      build();
      mood(c, 0.3);
      paper(s, `Resident Begins Forty-Foot Vessel on ${sname(s, c.street)}`, `${nm(c)} has begun construction of a timber vessel in a driveway on ${sname(s, c.street)}, with a permit. Neighbours report hammering from dawn. ${c.first} reports that the animals are "a later phase."`, 3);
      ledger(s, `${nm(c)} was permitted to build a forty-foot vessel in a driveway on ${sname(s, c.street)}.`, [nm(c)], 2);
      return `Approved. The keel is laid. The animals are a later phase.`;
    }
    if (s.order < 0.5) {
      build();
      paper(s, `Vessel Rises Overnight on ${sname(s, c.street)} Despite Denied Permit`, `A forty-foot timber hull appeared in a driveway on ${sname(s, c.street)} between dusk and dawn. The Town had denied the permit. The Town has been invited to the launch.`, 3);
      return `Denied. ${nm(c)} built it at night. The Town is invited to the launch.`;
    }
    mood(c, -0.3);
    pulse(s, c.street, "rage", 0.15);
    return `Denied. ${nm(c)} has stacked the timber in the drive and is looking at it.`;
  },
  lapse: (ctx, doc) => {
    const c = cit(ctx.state, doc.sender);
    if (c) {
      c.tags.push("ark");
      pulse(ctx.state, c.street, "bargaining", 0.2);
      queue(ctx, "complaint.ark", { street: c.street, owner: c.id });
    }
    return "The vessel is under way. So is the application, somewhere.";
  },
});

