define("question.real", {
  cooldown: 2,
  maxPerMonth: 8,
  make: (ctx, p) => {
    const c = senderOf(ctx, p);
    if (!c) return null;
    const other = neighbour(ctx, c);
    return {
      kind: "question",
      title: "Inquiry: The Object",
      body: `${nm(c)} would like to know, officially, whether the object is real, whether it is going to miss, and whether the Town has a position. ${c.first} notes that ${other ? nm(other) : "a neighbour"} on ${sname(ctx.state, c.street)} says it is a weather balloon, and that ${other?.first ?? "the neighbour"} has been right before, about the weather.`,
      options: [
        { id: "real", label: "It is real and it will not miss" },
        { id: "noposition", label: "The Town has no position" },
        { id: "exaggerated", label: "Reports are exaggerated" },
      ],
      sender: c.id,
      senderLabel: nm(c),
      priority: 3,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    if (option === "real") {
      spreadBelief(s, c.street, "real", 0.95, 0.6);
      spreadBelief(s, c.street, "miss", 0.05, 0.4);
      pulse(s, c.street, "denial", -0.2);
      pulse(s, c.street, "duty", 0.1);
      pushStatement(s, "answer-real", `The object is real and it will not miss. (Written answer to ${nm(c)}.)`, "honest", { fact: "real", value: true }, "answer");
      return `Answered: real, will not miss. ${c.first} read the answer aloud on the porch.`;
    }
    if (option === "noposition") {
      spreadBelief(s, c.street, "miss", 0.5, 0.3);
      return `Answered: the Town has no position. ${sname(s, c.street)} has taken several.`;
    }
    spreadBelief(s, c.street, "real", 0.3, 0.6);
    pulse(s, c.street, "denial", 0.3);
    mood(c, 0.1);
    pushStatement(s, "answer-real-lie", `Reports concerning the object are exaggerated. (Written answer to ${nm(c)}.)`, "lie", { fact: "real", value: false }, "answer");
    return `Answered: exaggerated. ${c.first} has cancelled the ark.`;
  },
});

