define("budget.weekly", {
  maxPerMonth: 4,
  make: (ctx) => {
    const s = ctx.state;
    const week = Math.floor(s.day / 7) + 1;
    const actuary = s.citizens.find((c) => c.role === "actuary" && c.present && c.dept === "pension") ?? null;
    const staff = s.citizens.filter((c) => c.dept && c.present && c.working).length;
    const revenue = Math.round(20 + 40 * s.trust * s.order);
    const payroll = Math.round(staff * 0.9);
    const variance = revenue - payroll;
    const fund = Math.max(0, 420 - (s.flags.includes("embezzled") ? 180 : 0) - (isActive(s, "raidPension") ? 400 : 0));
    return {
      kind: "budget",
      title: `Weekly Budget Reconciliation, Week ${week}`,
      body: `Revenue: ${revenue}. Payroll: ${payroll}. Variance: ${variance >= 0 ? "+" : ""}${variance}.\n\nPer Section 7.1 of the Charter the budget must balance. The pension fund stands at ${fund}, with obligations extending to the year 2061. ${actuary ? `${nm(actuary)} notes that this is still the law, and that ${actuary.first} did not write it.` : "The Pension Office is unstaffed and the figures are the Town Manager's own."}`,
      options: [
        { id: "cut", label: "Cut payroll" },
        { id: "raid", label: "Draw on the pension fund" },
        { id: "certify", label: "Certify as balanced" },
        { id: "defer", label: "Defer" },
      ],
      sender: actuary?.id ?? null,
      senderLabel: actuary ? `${nm(actuary)}, Pension Office` : "Pension Office (unstaffed)",
      priority: 7,
    };
  },
  resolve: (ctx, _doc, option) => {
    const s = ctx.state;
    s.budgetWeeks++;
    if (option === "cut") {
      s.treasury += 15;
      let n = 0;
      for (const c of s.citizens) {
        if (c.dept && c.present) {
          c.prop.flight = clamp(c.prop.flight + 0.15);
          if (ctx.rng.chance(0.15) && c.coping !== "quiet") {
            c.coping = "flight";
            c.copingSince = s.day;
            n++;
          }
        }
      }
      s.budgetWeeksBalanced++;
      ledger(s, `Payroll was cut to balance the week's budget. ${n} staff began looking at the door.`, [], 2);
      return `Balanced by cutting payroll. ${n} staff have begun looking at the door.`;
    }
    if (option === "raid") {
      s.treasury += 40;
      s.morale = clamp(s.morale + 0.08);
      s.budgetWeeksBalanced++;
      const actuary = s.citizens.find((c) => c.role === "actuary" && c.present && c.dept === "pension");
      if (actuary) {
        actuary.dept = null;
        actuary.working = false;
        actuary.tags.push("resigned");
        ledger(s, `${nm(actuary)} resigned as actuary after the pension fund was used to balance the weekly budget.`, [nm(actuary)], 3);
        paper(s, "Actuary Resigns; Pension Fund 'Reconciled'", `${nm(actuary)} has resigned from the Pension Office after the Town drew on the fund to balance the week. The fund's obligations extend to 2061. The actuary's do not.`, 3);
        return `Balanced from the pension fund. ${nm(actuary)} has resigned and taken the calculator.`;
      }
      return "Balanced from the pension fund. There was nobody left to object.";
    }
    if (option === "certify") {
      if (s.services.records >= 0.5) {
        s.budgetWeeksBalanced++;
        return "Certified as balanced. The Records Department would like it noted that it noted.";
      }
      s.trust = clamp(s.trust - 0.03);
      return "Certified as balanced by the Town Manager alone, the Records Department being short-staffed. The certification has been placed in the file, which has been placed on the desk.";
    }
    return "Deferred. The budget remains unbalanced, which Section 7.1 does not permit, and which Section 7.1 cannot, at present, do anything about.";
  },
  lapse: (ctx) => {
    ctx.state.budgetWeeks++;
    return "Unreconciled. The variance has been carried forward to a week that will not arrive.";
  },
});

define("editor.interview", {
  maxPerMonth: 3,
  make: (ctx) => {
    const s = ctx.state;
    const ed = role(s, "editor");
    if (!ed) return null;
    return {
      kind: "question",
      title: `Interview Request: the ${s.paperName}`,
      body: `${nm(ed)} requests twenty minutes with the Acting Town Manager for a piece on where things stand. Questions attached. Question one is "well?"`,
      options: [
        { id: "honest", label: "Give an honest interview" },
        { id: "reassure", label: "Give a reassuring interview" },
        { id: "decline", label: "Decline" },
      ],
      sender: ed.id,
      senderLabel: `${nm(ed)}, editor`,
      priority: 5,
    };
  },
  resolve: (ctx, _doc, option) => {
    const s = ctx.state;
    const out = s.streets.filter((x) => !x.water || !x.power).length;
    if (option === "honest") {
      spreadBelief(s, null, "real", 0.95, 0.3);
      spreadBelief(s, null, "federal", 0.1, 0.3);
      s.trust = clamp(s.trust + 0.04);
      pulseAll(s, "denial", -0.1);
      paper(s, `Acting Town Manager: "It's Real, It Won't Miss, and ${out ? `${out} Streets Have No Water` : "the Water Is Fine"}"`, `In an interview with this paper the Acting Town Manager confirmed that the object is real, that it will not miss, that there is no bunker, and that the Federal office has stopped answering. Asked what the plan was, the Town Manager said "this," and indicated the desk.`, 4);
      return `Given. The headline writes itself, and has.`;
    }
    if (option === "reassure") {
      s.trust = clamp(s.trust + 0.03);
      s.morale = clamp(s.morale + 0.04);
      pushStatement(s, "interview", "All municipal services are operating normally and will continue to.", "reassuring", { fact: "services", value: true }, "bulletin");
      paper(s, `Town Manager: "Services Normal, Spirits High, Object Noted"`, `In an interview with this paper the Acting Town Manager described municipal services as normal and the mood of the town as resilient. Asked about the object, the Town Manager said it had been noted.`, 3);
      return "Given. The paper has run it under a photograph of the desk.";
    }
    s.trust = clamp(s.trust - 0.02);
    paper(s, "Town Manager Declines to Comment; Column Inches Filled With Weather", `The Acting Town Manager declined to be interviewed. The forecast is for clear skies, which the editor notes is now a complicated thing to print.`, 2);
    return "Declined. The paper has printed the weather, at length.";
  },
});

