// Public API of the simulation. The UI and the headless runner only use this module.

import { Rng } from "./rng";
import { bulletinOptions } from "./bulletin";
import { computeServices, endDay } from "./day";
import { resolveDoc } from "./documents";
import { modifiers } from "./ordinances";
import type { Action, TownState } from "./types";
import { generateTown } from "./worldgen";

export function newGame(seed: number): TownState {
  const state = generateTown(seed);
  computeServices(state);
  state.bulletinOptions = bulletinOptions(state, modifiers(state));
  return state;
}

export class ActionError extends Error {}

/** Apply one player action in place. Throws ActionError for illegal actions; state is unchanged in that case. */
export function applyAction(state: TownState, action: Action): void {
  if (state.ended) throw new ActionError("The month is over.");
  const rng = Rng.fromState(state.rng);
  switch (action.type) {
    case "stamp": {
      const doc = state.inTray.find((d) => d.id === action.docId);
      if (!doc || doc.status !== "pending") throw new ActionError("No such document in the in-tray.");
      if (doc.chosen === "defer") throw new ActionError("Already deferred today.");
      if (!doc.options.some((o) => o.id === action.option)) throw new ActionError("Not an option on this document.");
      if (state.stampsLeft <= 0) throw new ActionError("No stamps left today.");
      if (!state.office.held) throw new ActionError("You no longer hold the office.");
      state.stampsLeft--;
      resolveDoc(state, rng, doc, action.option);
      break;
    }
    case "bulletin": {
      if (!state.bulletinOptions.some((o) => o.id === action.id)) throw new ActionError("Not a bulletin option today.");
      state.bulletinToday = action.id;
      break;
    }
    case "reassign": {
      const c = state.citizens.find((x) => x.id === action.citizenId);
      if (!c || !c.present || !c.dept) throw new ActionError("Not a municipal employee.");
      if (!state.office.held) throw new ActionError("You no longer hold the office.");
      c.dept = action.dept;
      computeServices(state);
      break;
    }
    case "endDay":
      endDay(state, rng);
      break;
  }
  state.actions.push(action);
  state.rng = rng.state;
}

export function replay(seed: number, actions: Action[]): TownState {
  const state = newGame(seed);
  for (const a of actions) applyAction(state, a);
  return state;
}

export function serialize(state: TownState): string {
  return JSON.stringify(state);
}

export function deserialize(text: string): TownState {
  const s = JSON.parse(text) as TownState;
  if (s.version !== 2) throw new Error("Unsupported save version.");
  return s;
}
