// The daily bulletin: one line to the town, and the day the town finds out whether it was true.

import type { Rng } from "./rng";
import type { Modifiers } from "./coping";
import { meanBelief, pulseAll, spreadBelief } from "./coping";
import { ledger, paper } from "./log";
import type { BulletinOption, Claim, ClaimFact, Statement, Tone, TownState } from "./types";
import { clamp, listNames } from "./util";

export function outageStreets(state: TownState): string[] {
  return state.streets.filter((s) => !s.water || !s.power).map((s) => s.name);
}

function factValue(state: TownState, fact: ClaimFact): boolean {
  switch (fact) {
    case "real":
      return true;
    case "miss":
      return false;
    case "bunker":
      return false;
    case "federal":
      return false;
    case "services":
      return outageStreets(state).length === 0;
  }
}

function proofDay(day: number, fact: ClaimFact): number {
  switch (fact) {
    case "real":
    case "miss":
      return Math.max(day + 1, 12);
    case "bunker":
      return day + 2;
    case "federal":
      return day + 3;
    case "services":
      return day + 1;
  }
}

export function pushStatement(
  state: TownState,
  id: string,
  text: string,
  tone: Tone,
  claim: Claim | null,
  source: Statement["source"],
): void {
  state.statements.push({
    id,
    day: state.day,
    proofDay: claim ? proofDay(state.day, claim.fact) : 0,
    text,
    tone,
    claim,
    source,
    checked: claim === null,
    truthful: null,
  });
}

export function bulletinOptions(state: TownState, mods: Modifiers): BulletinOption[] {
  const opts: BulletinOption[] = [];
  const out = outageStreets(state);
  opts.push({ id: "silence", text: "No bulletin today.", tone: "silence", claim: null });
  if (!state.office.held) return opts;

  if (out.length > 0) {
    if (!mods.optimism)
      opts.push({
        id: "services-honest",
        text: `Water or power is out on ${listNames(out.slice(0, 3))}${out.length > 3 ? " and elsewhere" : ""}. Crews are working. Crews are, at time of writing, ${Math.max(1, Math.round(state.services.water * 8))} people.`,
        tone: "honest",
        claim: { fact: "services", value: false },
      });
    opts.push({
      id: "services-lie",
      text: "All municipal services are operating normally.",
      tone: "lie",
      claim: { fact: "services", value: true },
    });
  } else {
    opts.push({
      id: "services-honest",
      text: "All municipal services are operating normally. This remains, for now, true.",
      tone: "honest",
      claim: { fact: "services", value: true },
    });
  }
  if (!mods.optimism)
    opts.push({
      id: "real-honest",
      text: `The object is real. It will not miss. The Town remains open and the office remains staffed.`,
      tone: "honest",
      claim: { fact: "real", value: true },
    });
  opts.push({
    id: "real-lie",
    text: "Reports concerning the object are exaggerated. Residents are asked to carry on.",
    tone: "lie",
    claim: { fact: "real", value: false },
  });
  opts.push({
    id: "federal-lie",
    text: "The Federal office has confirmed that assistance is on the way.",
    tone: "reassuring",
    claim: { fact: "federal", value: true },
  });
  opts.push({ id: "plan", text: "A plan is in place.", tone: "evasive", claim: null });
  if (meanBelief(state, "bunker") > 0.3)
    opts.push({
      id: "bunker-honest",
      text: "There is no bunker under the courthouse. There is a records annex. It is full of records.",
      tone: "honest",
      claim: { fact: "bunker", value: false },
    });
  if (state.cult?.registered)
    opts.push({
      id: "cult",
      text: `Services held at the bandstand by ${state.cult.name} are not municipal services and are not covered by the municipal insurance.`,
      tone: "evasive",
      claim: null,
    });
  if (mods.holiday)
    opts.push({
      id: "holiday",
      text: "A reminder that the weekly holiday will be observed. Offices will be closed. Offices were, residents may have noticed, mostly closed.",
      tone: "evasive",
      claim: null,
    });
  return opts;
}

export function applyBulletin(state: TownState, rng: Rng, id: string | null): void {
  const opt = state.bulletinOptions.find((o) => o.id === id) ?? state.bulletinOptions[0];
  if (!opt || opt.tone === "silence") {
    state.trust = clamp(state.trust - 0.01);
    pushStatement(state, "silence", "No bulletin.", "silence", null, "bulletin");
    return;
  }
  state.kpis.bulletinsIssued++;
  pushStatement(state, opt.id, opt.text, opt.tone, opt.claim, "bulletin");
  // A lie the town has already caught once buys nothing the second time.
  const caught = opt.claim ? (state.used[`false:${opt.claim.fact}`] ?? 0) : 0;
  const eyeroll = () => {
    state.morale = clamp(state.morale - 0.01);
  };
  switch (opt.id) {
    case "real-honest":
      spreadBelief(state, null, "real", 0.95, 0.4);
      spreadBelief(state, null, "miss", 0.05, 0.3);
      pulseAll(state, "denial", -0.2);
      pulseAll(state, "duty", 0.1);
      pulseAll(state, "quiet", 0.03);
      state.trust = clamp(state.trust + 0.02);
      break;
    case "real-lie":
      if (caught) {
        eyeroll();
        break;
      }
      spreadBelief(state, null, "real", 0.3, 0.4);
      pulseAll(state, "denial", 0.3);
      state.morale = clamp(state.morale + 0.03);
      break;
    case "federal-lie":
      if (caught) {
        eyeroll();
        break;
      }
      spreadBelief(state, null, "federal", 0.8, 0.4);
      state.morale = clamp(state.morale + 0.05);
      state.trust = clamp(state.trust + 0.02);
      break;
    case "services-honest":
      state.trust = clamp(state.trust + 0.02);
      break;
    case "services-lie":
      if (caught) {
        eyeroll();
        break;
      }
      state.morale = clamp(state.morale + 0.02);
      break;
    case "plan": {
      const n = state.used["plan"] ?? 0;
      state.used["plan"] = n + 1;
      state.trust = clamp(state.trust + 0.01 / (1 + 0.5 * n));
      state.morale = clamp(state.morale + 0.01 / (1 + 0.5 * n));
      if (n === 2) paper(state, `Town Manager: "A Plan Is in Place" (Third Day of Saying So)`, `For the third consecutive day the municipal bulletin has consisted of the sentence "A plan is in place." This paper has asked to see the plan. This paper has been told that it is in place.`, 2);
      if (n === 9) paper(state, `Plan Still in Place, Still Unseen; Residents Begin Drawing Their Own`, `Ten bulletins have now referred to a plan. Residents of several streets have begun drafting plans of their own and submitting them to Town Hall, where they are, presumably, in place.`, 2);
      break;
    }
    case "bunker-honest":
      spreadBelief(state, null, "bunker", 0.05, 0.5);
      state.trust = clamp(state.trust + 0.01);
      break;
    case "cult":
      state.order = clamp(state.order + 0.01);
      break;
    case "holiday":
      state.morale = clamp(state.morale + 0.01);
      break;
    default:
      break;
  }
  void rng;
}

const PENALTY: Record<ClaimFact, number> = { real: 0.15, miss: 0.1, bunker: 0.08, federal: 0.1, services: 0.05 };

/** The town tests old statements against what it can now see. */
export function checkStatements(state: TownState): void {
  let lostToday = 0;
  for (const st of state.statements) {
    if (st.checked || !st.claim || state.day < st.proofDay) continue;
    st.checked = true;
    const truth = factValue(state, st.claim.fact);
    st.truthful = st.claim.value === truth;
    if (st.truthful) {
      state.trust = clamp(state.trust + (st.source === "bulletin" ? 0.02 : 0.01));
      continue;
    }
    // The same lie, repeated, costs less each time: the town has stopped listening to that one.
    const key = `false:${st.claim.fact}`;
    const repeats = state.used[key] ?? 0;
    state.used[key] = repeats + 1;
    const penalty = Math.min(PENALTY[st.claim.fact] / (1 + 0.5 * repeats), Math.max(0, 0.3 - lostToday));
    lostToday += penalty;
    state.trust = clamp(state.trust - penalty);
    pulseAll(state, "rage", 0.15 / (1 + 0.5 * repeats));
    if (st.source === "bulletin") state.kpis.bulletinsFalse++;
    if (repeats >= 2) continue;
    const what = st.source === "bulletin" ? "bulletin" : st.source === "answer" ? "written answer" : "municipal order";
    const headline =
      st.claim.fact === "real"
        ? "Object Visibly Larger; Bulletin Described It as Exaggerated"
        : st.claim.fact === "federal"
          ? "Federal Assistance Fails to Arrive; Bulletin Said Otherwise"
          : st.claim.fact === "bunker"
            ? "Courthouse Sub-Basement Opened; Contains Records"
            : st.claim.fact === "miss"
              ? "Object Not Cancelled After All"
              : "Taps Dry Despite Bulletin";
    paper(state, headline, `The Town's ${what} of Day ${st.day} ("${st.text}") has been contradicted by events. A spokesman was not available, being also the Deputy Clerk.`, 3);
    ledger(state, `The ${what} of Day ${st.day} was proven false: "${st.text}"`, [], 2);
  }
}
