defineStory({
  id: "mayor",
  window: [9, 13],
  chance: 0.9,
  important: true,
  start: (s, rng) => {
    const pool = s.citizens.filter((c) => c.present && c.role === null && c.dept === null && c.age >= 45);
    if (!pool.length) return null;
    const c = rng.pick(pool);
    c.tags.push("mayor");
    c.job = "the Mayor";
    return { c: c.id };
  },
  beats: [
    { template: "story.mayor.return" },
    { template: "story.mayor.petition", delay: [2, 3], when: (_s, st) => st.choices[0] === "refuse" || (st.choices[0] === "resign" && !st.params.mayorSigned) },
    { template: "story.mayor.press", delay: [2, 3], when: (_s, st) => st.choices[1] === "deny" },
  ],
});

function loseOfficeTo(s: TownState, who: string, headline: string, body: string): void {
  s.office = { held: false, lostDay: s.day, lostTo: who };
  s.stampsPerDay = 0;
  s.stampsLeft = 0;
  ledger(s, `The Acting Town Manager handed the office to ${who}. The parking pass was returned.`, [], 5);
  paper(s, headline, body, 5);
}

define("story.mayor.return", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    if (!c || !c.present) return null;
    return {
      kind: "memo",
      title: "Memorandum: Resumption of Office",
      body: `The Mayor, ${nm(c)}, having been with family, has returned and will resume the duties of the office at 9 a.m. tomorrow. The Mayor thanks the Deputy Clerk for "holding the fort" and requests the stamp, the parking pass, and the plant.`,
      options: [
        { id: "refuse", label: "Refuse pending Council" },
        { id: "resign", label: "Request a resignation in writing" },
        { id: "hand", label: "Hand over the office" },
      ],
      sender: c.id,
      senderLabel: `${nm(c)}, Mayor`,
      priority: 8,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    if (option === "hand") {
      loseOfficeTo(s, `the Mayor, ${nm(c)}`, "Mayor Returns From Family, Resumes Office; Deputy Clerk Thanked", `${nm(c)} resumed the office of Mayor this morning after ${s.day} days with family. The Deputy Clerk, who has run the town since the announcement, was thanked in a short ceremony and given back the Deputy Clerk's own desk. The plant has been located.`);
      return "Handed over. The Mayor has the stamp, the pass and the plant. You have your old desk, which was always yours.";
    }
    if (option === "refuse") {
      s.trust = clamp(s.trust - 0.03);
      c.coping = "rage";
      c.copingSince = s.day;
      mood(c, -0.3);
      paper(s, "Mayor Returns; Deputy Clerk Declines to Return Stamp", `${nm(c)} returned to Town Hall this morning to resume office and was told by the Deputy Clerk that the Charter requires Council to confirm any appointment, including, the Deputy Clerk said, "yours." Council could not be reached. The Mayor is in the lobby.`, 4);
      ledger(s, `The Mayor returned and asked for the stamp. The Deputy Clerk declined, citing the Charter. The Mayor is in the lobby.`, [nm(c)], 3);
      return "Refused, pending Council. Council cannot be reached. The Mayor is in the lobby.";
    }
    const story = storyOf(s, doc);
    if (ctx.rng.chance(0.6)) {
      if (story) story.params.mayorSigned = true;
      c.coping = "quiet";
      c.copingSince = s.day;
      ledger(s, `The Mayor resigned, in writing, at the Deputy Clerk's request. The letter was short.`, [nm(c)], 3);
      paper(s, "Mayor Resigns in Writing; Letter Short", `${nm(c)} resigned as Mayor this morning in a letter of one sentence, at the request of the Deputy Clerk. The Mayor has gone back to family. The plant stays.`, 3);
      return "The Mayor signed. The letter was short. The plant stays.";
    }
    c.coping = "rage";
    c.copingSince = s.day;
    return "The Mayor declined to resign and has gone to the paper.";
  },
});

define("story.mayor.petition", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    if (!c || !c.present) return null;
    return {
      kind: "petition",
      title: "Petition: Reinstate the Mayor",
      body: `${ctx.rng.int(150, 1200)} signatures. The petitioners call for the immediate reinstatement of ${nm(c)} as Mayor, "who at least was elected," and the return of the Deputy Clerk to the Deputy Clerk's desk, "which has a plant on it now." The Mayor has signed twice.`,
      options: AD,
      sender: c.id,
      senderLabel: `${nm(c)} and others`,
      priority: 6,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    if (option === "approve") {
      loseOfficeTo(s, `the Mayor, ${nm(c)}`, "Mayor Reinstated by Petition; Deputy Clerk Returns to Desk", `${nm(c)} was reinstated as Mayor this morning on the strength of a petition approved by the Deputy Clerk, who has returned to the Deputy Clerk's desk. The plant has been moved. The stamp has not.`);
      return "Approved. The Mayor is reinstated. You have your desk back. The plant has been moved.";
    }
    s.trust = clamp(s.trust - 0.02);
    pulse(s, c.street, "rage", 0.2);
    return "Denied. The Mayor has announced a press conference.";
  },
});

define("story.mayor.press", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    if (!c || !c.present) return null;
    return {
      kind: "memo",
      title: "Notice: Rival Press Conference, Courthouse Steps",
      body: `${nm(c)} gives notice of a press conference on the courthouse steps at noon to address "the situation at Town Hall." The press has been invited. The press is one person, who has replied that the press will be at lunch.`,
      options: FILE,
      sender: c.id,
      senderLabel: `${nm(c)}, Mayor (disputed)`,
      priority: 3,
    };
  },
  resolve: (ctx, doc) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    c.tags.push("leaving");
    paper(s, "Mayor Holds Rival Press Conference; Attendance Four, Including Dog", `${nm(c)} addressed the town from the courthouse steps at noon on "the situation at Town Hall." Four people attended, one of them a dog. The Mayor spoke for eleven minutes and then, by the Mayor's own account, went back to being with family.`, 3);
    ledger(s, `The Mayor held a press conference attended by four people and a dog, then went back to being with family.`, [nm(c)], 3);
    return "Filed. Four attended, one a dog. The Mayor has gone back to family.";
  },
});

