defineStory({
  id: "auditor",
  window: [17, 22],
  chance: 0.9,
  important: true,
  start: (_s, rng) => ({ name: `${rng.pick(N.FIRST_NAMES)} ${rng.pick(N.LAST_NAMES)}` }),
  beats: [
    { template: "story.auditor.arrival" },
    { template: "story.auditor.findings", delay: [3, 4], when: (_s, st) => st.choices[0] === "cooperate" },
    { template: "story.auditor.last", at: [28, 29] },
  ],
});

define("story.auditor.arrival", {
  make: (_ctx, p) => ({
    kind: "federal",
    title: `Notice of Arrival: Federal Auditor ${String(p.name)}`,
    body: `${String(p.name)}, regional auditor, has arrived in person, the Federal office's mailbox being no longer monitored and ${String(p.name).split(" ")[0]} being, by ${String(p.name).split(" ")[0]}'s own account, "the only one still coming in." The auditor requests the Town's records for the fiscal year following, a desk, and a word about the lobby.`,
    options: [
      { id: "cooperate", label: "Provide the records" },
      { id: "refuse", label: "Refuse" },
      { id: "hire", label: "Offer the auditor a job" },
    ],
    sender: null,
    senderLabel: `${String(p.name)}, Federal Office (Regional)`,
    priority: 6,
  }),
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const name = String(doc.payload.name);
    if (option === "cooperate") {
      paper(s, "Federal Auditor Arrives in Person; Last Federal Employee Still Working", `${name}, auditor, arrived at Town Hall yesterday by car, the Federal office having stopped answering its mail. ${name.split(" ")[0]} was given the Town's records and a desk in the Records Department, and has begun. Asked why, the auditor said "it's Tuesday."`, 3);
      ledger(s, `The Town gave its records to ${name}, the last Federal employee still working.`, [name], 2);
      return `The records were provided. ${name.split(" ")[0]} has begun, and has asked for a lamp.`;
    }
    if (option === "hire") {
      s.flags.push("auditor-hired");
      const rec = s.departments.find((d) => d.id === "records");
      if (rec) rec.required = Math.max(3, rec.required - 1);
      ledger(s, `${name}, the Federal auditor, joined the Records Department. The Federal office was not informed, having no one to inform.`, [name], 3);
      paper(s, "Federal Auditor Joins Records Department; Federal Office Not Informed", `${name}, who arrived to audit the Town on behalf of a Federal office that has stopped answering its mail, has accepted a position in the Records Department instead. ${name.split(" ")[0]} will audit the Town from the inside, which ${name.split(" ")[0]} described as "more efficient."`, 3);
      return `Hired. ${name.split(" ")[0]} starts in Records tomorrow and has asked about the pension.`;
    }
    paper(s, "Federal Auditor Refused Records; Sits in Lobby", `${name}, Federal auditor, was refused the Town's records yesterday and has taken a seat in the lobby, where ${name.split(" ")[0]} remains, with a flask. Asked how long ${name.split(" ")[0]} intends to stay, the auditor said "I have the time."`, 2);
    return `Refused. ${name.split(" ")[0]} is in the lobby with a flask and, by ${name.split(" ")[0]}'s own account, the time.`;
  },
});

define("story.auditor.findings", {
  make: (_ctx, p) => ({
    kind: "federal",
    title: "Preliminary Audit Findings: Fourteen Items",
    body: `${String(p.name)} reports fourteen preliminary findings, all concerning the pension fund, one concerning the plant, and one, outside the scope of the audit, concerning the lobby. The Town may accept the findings or dispute them. The auditor notes that nobody will read either response, and that ${String(p.name).split(" ")[0]} will.`,
    options: [
      { id: "accept", label: "Accept the findings" },
      { id: "dispute", label: "Dispute the findings" },
    ],
    sender: null,
    senderLabel: `${String(p.name)}, auditor`,
    priority: 4,
  }),
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const name = String(doc.payload.name);
    if (option === "accept") {
      s.trust = clamp(s.trust + 0.02);
      ledger(s, `The Town accepted fourteen audit findings from ${name}. One was about the lobby.`, [name], 2);
      return "Accepted. The auditor has initialled the acceptance and, separately, the lobby.";
    }
    paper(s, "Town Disputes Audit; Disputes Existence of Year Audited", `The Town has formally disputed the Federal auditor's preliminary findings on the grounds that the fiscal year audited "does not and will not exist." The auditor has noted the dispute and described it as "a finding."`, 2);
    return `Disputed. The Town's position is that the year does not exist. ${name.split(" ")[0]} has written that down as a fifteenth finding.`;
  },
});

define("story.auditor.last", {
  make: (ctx, p) => {
    const hired = ctx.state.flags.includes("auditor-hired");
    const name = String(p.name);
    return hired
      ? {
          kind: "staffing",
          title: `Request: A Desk by the Window, ${name}`,
          body: `${name}, Records Department, requests reassignment to the desk by the window for the remaining days, the desk being unoccupied and the window being, in ${name.split(" ")[0]}'s words, "the point now."`,
          options: AD,
          sender: null,
          senderLabel: `${name}, Records`,
          priority: 3,
        }
      : {
          kind: "federal",
          title: "Audit Closed: Final Report",
          body: `The audit of the Town is closed. Findings: fourteen, or fifteen. Recommendations: none. ${name} thanks the Town for its cooperation, or its lobby, and will now go and sit on the steps, which ${name.split(" ")[0]} has not done since arriving.`,
          options: FILE,
          sender: null,
          senderLabel: `${name}, auditor`,
          priority: 3,
        };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const name = String(doc.payload.name);
    if (doc.kind === "staffing") {
      if (option === "approve") {
        ledger(s, `${name} got the desk by the window on Day ${s.day}, and looked out of it.`, [name], 3);
        return `Approved. ${name.split(" ")[0]} has the window.`;
      }
      return `Denied. ${name.split(" ")[0]} has moved the chair instead.`;
    }
    ledger(s, `${name} closed the audit on Day ${s.day} with fourteen findings and no recommendations, and went to sit on the steps.`, [name], 2);
    return "Filed. The auditor is on the steps.";
  },
});

