defineStory({
  id: "wedding",
  window: [4, 16],
  chance: 0.7,
  start: (s, rng) => {
    const free = s.citizens.filter((c) => c.present && !c.tags.includes("married") && !c.tags.includes("engaged") && c.role === null);
    if (free.length < 2) return null;
    const c = rng.pick(free);
    const partners = free.filter((x) => x.id !== c.id && Math.abs(x.age - c.age) < 20);
    if (!partners.length) return null;
    const partner = rng.pick(partners);
    c.tags.push("engaged");
    partner.tags.push("engaged");
    return { c: c.id, partner: partner.id, fickle: rng.chance(0.5) };
  },
  beats: [
    { template: "permit.marriage" },
    { template: "story.wedding.square", delay: [2, 3], when: (_s, st) => st.choices[0] === "approve" },
    { template: "story.wedding.dissolution", delay: [5, 7], when: (_s, st) => st.choices[0] === "approve" && st.params.fickle === true },
  ],
});

define("permit.marriage", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    const partner = cit(ctx.state, p.partner);
    if (!c || !partner || !c.present || !partner.present) return null;
    return {
      kind: "permit",
      title: "Marriage Licence Application (Expedited)",
      body: `${nm(c)} and ${nm(partner)} apply for a marriage licence, expedited, having met on ${ctx.rng.pick(N.WEEKDAYS)}. The statutory waiting period is thirty days. The applicants have attached a calendar with the relevant days crossed out, and a note reading "please."`,
      options: STD,
      sender: c.id,
      senderLabel: `${nm(c)} and ${nm(partner)}`,
      priority: 3,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    const partner = cit(s, doc.payload.partner);
    if (!c || !partner) return "Filed.";
    if (option === "approve") {
      for (const x of [c, partner]) {
        x.tags.push("married");
        mood(x, 0.3);
        pulse(s, x.street, "hedonism", 0.15);
      }
      ledger(s, `${nm(c)} and ${nm(partner)} were married on Day ${s.day}, expedited, the waiting period having been waived on the grounds that there wasn't one.`, [nm(c), nm(partner)], 2);
      return `Approved. The waiting period is waived. The Records Department will witness, and has asked for tissues.`;
    }
    for (const x of [c, partner]) mood(x, -0.3);
    pulse(s, c.street, "rage", 0.1);
    return `Denied. The waiting period stands. The applicants have pointed at the sky, together, which was the point.`;
  },
  lapse: (ctx, doc) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    const partner = cit(s, doc.payload.partner);
    if (c && partner) for (const x of [c, partner]) x.tags.push("married");
    return s.cult ? `They were married at the bandstand by ${s.cult.name}, which has forms.` : "They were married by a notary, who had the forms and no instructions not to.";
  },
});

define("story.wedding.square", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    const partner = cit(ctx.state, p.partner);
    if (!c || !partner || !c.present || !partner.present) return null;
    return {
      kind: "permit",
      title: "Request: Use of the Square, Wedding, Everyone Invited",
      body: `${nm(c)} and ${nm(partner)} request the use of the square on Saturday for a wedding to which everyone is invited, "everyone" being underlined. The band has agreed to play the one song it knows. Catering will be whatever people bring. The applicants ask that the Town come, and that the Town bring something.`,
      options: AD,
      sender: c.id,
      senderLabel: `${nm(c)} and ${nm(partner)}`,
      priority: 3,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    const partner = cit(s, doc.payload.partner);
    if (!c || !partner) return "Filed.";
    if (option === "approve") {
      pulseAll(s, "hedonism", 0.08);
      pulseAll(s, "piety", 0.05);
      s.morale = clamp(s.morale + 0.03);
      ledger(s, `${nm(c)} and ${nm(partner)} were married in the square on Day ${s.day}. Everyone came. The band played the one song it knows, twice. The Town brought a lamp.`, [nm(c), nm(partner)], 3);
      paper(s, "Wedding in the Square; Everyone Came; Band Plays Its Song Twice", `${nm(c)} and ${nm(partner)} were married in the square on Saturday before what the ${s.paperName} estimates was everyone. The band played its song twice. The catering was whatever people brought, which was a great deal. The Acting Town Manager brought a lamp.`, 3);
      return "Approved. Everyone came. The band played twice. You brought a lamp.";
    }
    return `Denied. They were married on the steps, which are not the square, and everyone came anyway.`;
  },
});

define("story.wedding.dissolution", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    const partner = cit(ctx.state, p.partner);
    if (!c || !partner || !c.present || !partner.present) return null;
    return {
      kind: "permit",
      title: `Application for Dissolution (Expedited): ${c.last} and ${partner.last}`,
      body: `${nm(c)} and ${nm(partner)} apply for the dissolution of their marriage, expedited, on the grounds that "it was a Tuesday thing." Both have signed. Both have added "no hard feelings." One has underlined it; the other has drawn a small heart next to it, which is noted.`,
      options: STD,
      sender: c.id,
      senderLabel: `${nm(c)} and ${nm(partner)}`,
      priority: 2,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    const partner = cit(s, doc.payload.partner);
    if (!c || !partner) return "Filed.";
    if (option === "approve") {
      for (const x of [c, partner]) mood(x, 0.1);
      ledger(s, `${nm(c)} and ${nm(partner)}'s marriage, a Tuesday thing, was dissolved amicably on Day ${s.day}. A small heart was noted.`, [nm(c), nm(partner)], 2);
      return "Approved. Amicable. The small heart has been noted in the file.";
    }
    return "Denied. The marriage continues, with notes, from both sides, and the heart.";
  },
});

// ======================================================================
// The time capsule
// ======================================================================

defineStory({
  id: "capsule",
  window: [6, 14],
  chance: 0.6,
  start: (s) => {
    const c = s.citizens.find((x) => x.role === "council" && x.agenda === "legacy" && x.present);
    return c ? { c: c.id } : null;
  },
  beats: [
    { template: "story.capsule.proposal" },
    { template: "story.capsule.contents", delay: [2, 3], when: (_s, st) => st.choices[0] === "approve" },
    { template: "story.capsule.burial", at: [27, 29], when: (_s, st) => st.choices[0] === "approve" },
  ],
});

define("story.capsule.proposal", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    if (!c || !c.present) return null;
    return {
      kind: "ordinance",
      title: "Proposal: Municipal Time Capsule",
      body: `Councillor ${nm(c)} proposes that the Town bury a time capsule in the square, to be opened in one hundred years "by whoever is around." Budget: a box and a plaque. The Councillor asks that the plaque bear the Councillor's name, in a size the Councillor has specified, in a drawing.`,
      options: AD,
      sender: c.id,
      senderLabel: `Councillor ${nm(c)}`,
      priority: 4,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    if (!c) return "Filed.";
    if (option === "approve") {
      s.treasury -= 5;
      mood(c, 0.3);
      trustOf(c, 0.1);
      return `Approved. A box has been ordered, and a plaque, in the specified size, which is large.`;
    }
    mood(c, -0.3);
    trustOf(c, -0.15);
    return `Declined. Councillor ${c.last} has bought a box anyway and is filling it at home.`;
  },
});

define("story.capsule.contents", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    if (!c || !c.present) return null;
    const hasArk = ctx.state.citizens.some((x) => x.tags.includes("ark"));
    const options = [
      { id: "records", label: "The records" },
      { id: "bulletins", label: "The bulletins to date" },
      { id: "nothing", label: "Nothing, sealed" },
    ];
    if (hasArk) options.splice(2, 0, { id: "ark", label: "The drawing of the ark" });
    return {
      kind: "question",
      title: "Request: Contents of the Capsule",
      body: `Councillor ${nm(c)} asks the Acting Town Manager to decide what goes in the capsule, the Councillor having "ideas" but "wanting it to be the Town's." The box is on the desk. It is smaller than the plaque.`,
      options,
      sender: c.id,
      senderLabel: `Councillor ${nm(c)}`,
      priority: 3,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const story = storyOf(s, doc);
    const what =
      option === "records"
        ? "the Town's records, as many as fit, which was the index"
        : option === "bulletins"
          ? "every bulletin issued, stapled, with a cover sheet reading PLAN"
          : option === "ark"
            ? "the drawing of the ark, with the animals the applicant did not own"
            : "nothing, sealed, with a note explaining that this was deliberate";
    if (story) story.params.contents = what;
    ledger(s, `The time capsule was filled with ${what}.`, [], 2);
    return `Decided. The capsule holds ${what}. The lid is on.`;
  },
});

define("story.capsule.burial", {
  make: (ctx, p) => {
    const c = cit(ctx.state, p.c);
    if (!c || !c.present) return null;
    return {
      kind: "permit",
      title: "Permit: Burial of the Capsule, Courthouse Square, Saturday",
      body: `Councillor ${nm(c)} applies to bury the time capsule in the square on Saturday with a short ceremony, the band, and the plaque. The plaque reads OPEN IN 100 YEARS. Someone has added, in pen, "or whenever." The Councillor would like the pen traced and has asked the Chief.`,
      options: AD,
      sender: c.id,
      senderLabel: `Councillor ${nm(c)}`,
      priority: 4,
    };
  },
  resolve: (ctx, doc, option) => {
    const s = ctx.state;
    const c = cit(s, doc.sender);
    const contents = String(storyOf(s, doc)?.params.contents ?? "what was decided");
    if (!c) return "Filed.";
    if (option === "approve") {
      s.flags.push("capsule");
      ledger(s, `The time capsule was buried in the square on Day ${s.day}, containing ${contents}. The plaque reads OPEN IN 100 YEARS, or whenever.`, [nm(c)], 4);
      paper(s, "Time Capsule Buried in Square; Plaque Amended in Pen", `The Town's time capsule was buried in the square on Saturday in a short ceremony with the band. The plaque reads OPEN IN 100 YEARS. An amendment in pen, "or whenever," has been left, the Chief having declined to trace it. The capsule contains ${contents}.`, 3);
      return "Approved. Buried, with the band. The amendment stays.";
    }
    mood(c, -0.2);
    return `Denied. Councillor ${c.last} has buried it in the garden, with the plaque, which does not fit.`;
  },
});
