import type { TownState } from "./types";

/** Record a consequential outcome with the names it landed on. Weight 1 is trivia; 5 is a front page. */
export function ledger(state: TownState, text: string, names: string[], weight: number): void {
  state.ledger.push({ day: state.day, text, names, weight });
}

/** Offer the paper a story. The editor prints the heaviest few each day. */
export function paper(state: TownState, headline: string, body: string, weight: number): void {
  state.paper.push({ day: state.day, headline, body, weight });
}

export function event(state: TownState, text: string): void {
  state.events.push(text);
}
