// Build a town from a seed.

import { Rng } from "./rng";
import * as N from "./names";
import { arcWeight } from "./coping";
import { initialInTray } from "./documents";
import {
  COPING_STYLES,
  DEPT_IDS,
  type Agenda,
  type Citizen,
  type CopingStyle,
  type Department,
  type DeptId,
  type Street,
  type TownState,
} from "./types";
import { clamp } from "./util";

const DEPT_META: Record<DeptId, { name: string; required: number; initial: number }> = {
  water: { name: "Water", required: 8, initial: 9 },
  power: { name: "Power", required: 8, initial: 9 },
  police: { name: "Police", required: 12, initial: 13 },
  sanitation: { name: "Sanitation", required: 10, initial: 11 },
  parks: { name: "Parks", required: 6, initial: 7 },
  records: { name: "Records", required: 6, initial: 7 },
  pension: { name: "Pension Office", required: 4, initial: 4 },
};

export const CITIZEN_COUNT = 200;
export const STREET_COUNT = 12;

export function generateTown(seed: number): TownState {
  const rng = new Rng(seed);
  const townName = rng.pick(N.TOWN_PREFIX) + rng.pick(N.TOWN_SUFFIX);
  const asteroidName = rng.pick(N.ASTEROID_NAMES);
  const asteroid = { designation: `${rng.int(1000, 9999)} ${asteroidName}`, name: asteroidName };
  const population = 30000 + rng.int(0, 25000);
  const paperName = `${townName} ${rng.pick(N.PAPER_NAMES)}`;

  const streetNames = rng.shuffle([...N.STREET_NAMES]).slice(0, STREET_COUNT - 1);
  const streets: Street[] = [{ id: 0, name: "Main Street", households: 40, water: true, power: true }];
  streetNames.forEach((n, i) =>
    streets.push({ id: i + 1, name: `${n} ${rng.pick(N.STREET_TYPES)}`, households: rng.int(60, 180), water: true, power: true }),
  );

  const departments: Department[] = DEPT_IDS.map((id) => ({ id, name: DEPT_META[id].name, required: DEPT_META[id].required }));

  const citizens: Citizen[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < CITIZEN_COUNT; i++) {
    let first = rng.pick(N.FIRST_NAMES);
    let last = rng.pick(N.LAST_NAMES);
    let guard = 0;
    while (seen.has(`${first} ${last}`) && guard++ < 20) {
      first = rng.pick(N.FIRST_NAMES);
      last = rng.pick(N.LAST_NAMES);
    }
    seen.add(`${first} ${last}`);
    const age = rng.int(19, 84);
    const traits = { sociable: rng.next(), stubborn: rng.next(), anxious: rng.next() };
    const prop = {} as Record<CopingStyle, number>;
    for (const s of COPING_STYLES) prop[s] = 0.1 + rng.next() * 0.6;
    // Everyone has a way they are going to cope, and a fallback.
    const primary = rng.pick(COPING_STYLES.filter((s) => s !== "quiet"));
    const secondary = rng.pick(COPING_STYLES.filter((s) => s !== "quiet" && s !== primary));
    prop[primary] += 0.4;
    prop[secondary] += 0.2;
    if (age >= 60) {
      prop.piety += 0.2;
      prop.hedonism -= 0.15;
      prop.flight -= 0.1;
    }
    if (age < 30) {
      prop.hedonism += 0.2;
      prop.flight += 0.1;
      prop.duty -= 0.1;
    }
    prop.quiet += 0.2 * traits.anxious - 0.1;
    prop.hoarding += 0.15 * traits.anxious;
    prop.hedonism += 0.15 * traits.sociable;
    prop.piety += 0.05 * traits.sociable;
    prop.denial += 0.15 * traits.stubborn;
    prop.rage += 0.1 * traits.stubborn;
    for (const s of COPING_STYLES) prop[s] = clamp(prop[s], 0.02, 1);
    citizens.push({
      id: i,
      first,
      last,
      age,
      street: i % STREET_COUNT,
      job: age >= 66 ? "retired" : rng.pick(N.CIVILIAN_JOBS),
      dept: null,
      homeDept: null,
      role: null,
      agenda: null,
      coping: "denial",
      copingSince: 1,
      prop,
      traits,
      mood: rng.gauss() * 0.2,
      trustOffset: rng.gauss() * 0.1,
      beliefs: { real: clamp(0.75 + rng.gauss() * 0.15), miss: clamp(0.2 + rng.gauss() * 0.15), bunker: clamp(0.25 + rng.gauss() * 0.15), federal: clamp(0.3 + rng.gauss() * 0.15) },
      present: true,
      working: true,
      strikeUntil: 0,
      tags: [],
    });
  }

  // Municipal employment: fill each department from working-age citizens.
  const pool = rng.shuffle(citizens.filter((c) => c.age < 66));
  let cursor = 0;
  for (const id of DEPT_IDS) {
    for (let k = 0; k < DEPT_META[id].initial; k++) {
      const c = pool[cursor++];
      if (!c) break;
      c.dept = id;
      c.homeDept = id;
      c.job = `${DEPT_META[id].name} Department`;
      c.prop.duty = clamp(c.prop.duty + 0.25);
    }
  }

  // Named voices.
  const take = (pred: (c: Citizen) => boolean): Citizen | undefined => pool.slice(cursor).find((c) => c.role === null && pred(c));
  const agendas: Agenda[] = ["order", "party", "legacy"];
  for (const a of agendas) {
    const c = take((x) => x.dept === null && x.age >= 35);
    if (c) {
      c.role = "council";
      c.agenda = a;
      c.job = "council member";
    }
  }
  const chief = citizens.find((c) => c.dept === "police");
  if (chief) chief.role = "chief";
  const engineer = citizens.find((c) => c.dept === "water");
  if (engineer) {
    engineer.role = "engineer";
    engineer.prop.duty = 1;
    engineer.traits.stubborn = Math.max(engineer.traits.stubborn, 0.8);
  }
  const actuary = citizens.find((c) => c.dept === "pension");
  if (actuary) actuary.role = "actuary";
  const principal = take((x) => x.dept === null && x.age >= 40 && x.age < 66);
  if (principal) {
    principal.role = "principal";
    principal.job = "school principal";
  }
  const pastor = take((x) => x.dept === null && x.age >= 40);
  if (pastor) {
    pastor.role = "pastor";
    pastor.job = "pastor";
    pastor.prop.piety = 1;
  }
  const editor = take((x) => x.dept === null && x.age >= 30 && x.age < 66);
  if (editor) {
    editor.role = "editor";
    editor.job = `editor, the ${paperName}`;
  }

  // Day 1 coping, drawn from propensity shaped by the calendar.
  for (const c of citizens) {
    const weights = COPING_STYLES.map((s) => (s === "quiet" ? 0 : c.prop[s] * (0.3 + arcWeight(s, 1))));
    const total = weights.reduce((a, b) => a + b, 0);
    let r = rng.next() * total;
    let chosen: CopingStyle = "denial";
    for (let k = 0; k < COPING_STYLES.length; k++) {
      r -= weights[k] ?? 0;
      if (r <= 0) {
        chosen = COPING_STYLES[k] ?? "denial";
        break;
      }
    }
    c.coping = chosen;
  }

  const services = {} as Record<DeptId, number>;
  for (const id of DEPT_IDS) services[id] = 1;

  const state: TownState = {
    version: 2,
    seed,
    day: 1,
    ended: false,
    townName,
    originalName: townName,
    paperName,
    population,
    asteroid,
    citizens,
    streets,
    departments,
    services,
    streetPulse: streets.map(() => COPING_STYLES.map(() => 0)),
    inTray: [],
    queued: [],
    archive: [],
    nextDocId: 1,
    stampsPerDay: 8,
    stampsLeft: 8,
    ordinances: [],
    trust: 0.6,
    order: 0.8,
    morale: 0.5,
    treasury: 100,
    lowTrustDays: 0,
    cult: null,
    stories: [],
    bulletinToday: null,
    bulletinOptions: [],
    statements: [],
    ledger: [],
    paper: [],
    events: [],
    kpis: {
      permitsProcessed: 0,
      permitsApproved: 0,
      permitsDenied: 0,
      deferrals: 0,
      lapsed: 0,
      bulletinsIssued: 0,
      bulletinsFalse: 0,
      ordinancesSigned: 0,
      welfareChecks: 0,
      headcountStart: citizens.filter((c) => c.dept).length,
    },
    office: { held: true, lostDay: null, lostTo: null },
    used: {},
    flags: [],
    budgetWeeks: 0,
    budgetWeeksBalanced: 0,
    uptimeSum: 0,
    rng: 0,
    actions: [],
    epilogue: null,
  };
  state.inTray = initialInTray(state, rng);
  state.rng = rng.state;
  return state;
}
