// A photograph of the square for the evening edition, drawn from the state of the town.

import { copingCounts, presentCount } from "../sim/coping";
import type { CopingStyle, TownState } from "../sim/types";

function figure(x: number, y: number, h: number, pose: "stand" | "arms" | "kneel" | "sign" | "box" | "sit", shade = "#2b2a26"): string {
  const head = h * 0.16;
  const body = h * 0.5;
  if (pose === "kneel") {
    return `<g fill="${shade}"><circle cx="${x}" cy="${y - h * 0.55}" r="${head}"/><rect x="${x - h * 0.1}" y="${y - h * 0.45}" width="${h * 0.2}" height="${h * 0.3}"/><rect x="${x - h * 0.18}" y="${y - h * 0.18}" width="${h * 0.36}" height="${h * 0.18}"/></g>`;
  }
  if (pose === "sit") {
    return `<g fill="${shade}"><circle cx="${x}" cy="${y - h * 0.6}" r="${head}"/><rect x="${x - h * 0.1}" y="${y - h * 0.48}" width="${h * 0.2}" height="${h * 0.28}"/><rect x="${x - h * 0.1}" y="${y - h * 0.22}" width="${h * 0.3}" height="${h * 0.08}"/></g>`;
  }
  let extra = "";
  if (pose === "arms") extra = `<line x1="${x - h * 0.1}" y1="${y - body - head * 0.4}" x2="${x - h * 0.3}" y2="${y - h * 0.95}" stroke="${shade}" stroke-width="${h * 0.06}"/><line x1="${x + h * 0.1}" y1="${y - body - head * 0.4}" x2="${x + h * 0.3}" y2="${y - h * 0.95}" stroke="${shade}" stroke-width="${h * 0.06}"/>`;
  if (pose === "sign") extra = `<rect x="${x + h * 0.12}" y="${y - h * 1.15}" width="${h * 0.42}" height="${h * 0.3}" fill="#f7f6ee" stroke="${shade}" stroke-width="1"/><line x1="${x + h * 0.3}" y1="${y - h * 0.85}" x2="${x + h * 0.3}" y2="${y - h * 0.5}" stroke="${shade}" stroke-width="${h * 0.05}"/>`;
  if (pose === "box") extra = `<rect x="${x - h * 0.22}" y="${y - h * 0.62}" width="${h * 0.44}" height="${h * 0.26}" fill="#8a8470" stroke="${shade}" stroke-width="1"/>`;
  return `<g><circle cx="${x}" cy="${y - body - head * 1.3}" r="${head}" fill="${shade}"/><rect x="${x - h * 0.11}" y="${y - body - head * 0.4}" width="${h * 0.22}" height="${body}" fill="${shade}"/><rect x="${x - h * 0.1}" y="${y - h * 0.26}" width="${h * 0.08}" height="${h * 0.26}" fill="${shade}"/><rect x="${x + h * 0.02}" y="${y - h * 0.26}" width="${h * 0.08}" height="${h * 0.26}" fill="${shade}"/>${extra}</g>`;
}

/** Deterministic pseudo-random for layout only; never touches the sim. */
function hash(n: number): number {
  let x = (n + 1) * 2654435761;
  x = (x ^ (x >>> 15)) * 2246822519;
  x = (x ^ (x >>> 13)) * 3266489917;
  return ((x ^ (x >>> 16)) >>> 0) / 4294967296;
}

export interface SquareScene {
  svg: string;
  caption: string;
}

export function squarePhoto(state: TownState, day: number): SquareScene {
  const w = 760;
  const h = 250;
  const ground = 200;
  const t = Math.min(1, Math.max(0, (day - 1) / 29));
  const counts = copingCounts(state);
  const present = Math.max(1, presentCount(state));
  const frac = (s: CopingStyle) => counts[s] / present;
  const f = (flag: string) => state.flags.includes(flag);
  const lastNight = day >= 29;
  const night = f("roof") && day >= 25 ? true : lastNight ? !f("lights-on") : day >= 22 && frac("piety") > 0.2;
  const sky = night ? "#5a5650" : `rgb(${Math.round(214 - 30 * t)},${Math.round(212 - 40 * t)},${Math.round(204 - 50 * t)})`;
  const r = 4 + 70 * Math.pow(t, 2.1);
  const ox = w * 0.8;
  const oy = 62;

  const parts: string[] = [];
  parts.push(`<rect width="${w}" height="${h}" fill="${sky}"/>`);
  parts.push(`<circle cx="${ox}" cy="${oy}" r="${r * 1.8 + 6}" fill="#f0e8d8" opacity="${0.08 + 0.15 * t}"/>`);
  parts.push(`<circle cx="${ox}" cy="${oy}" r="${r}" fill="#1e1c19"/>`);

  // Water tower in the distance, with whatever has been painted on it.
  const towerWord = state.flags.find((x) => x.startsWith("tower-"))?.slice(6);
  parts.push(`<rect x="60" y="78" width="40" height="26" rx="4" fill="#8e8878"/><rect x="66" y="104" width="4" height="40" fill="#8e8878"/><rect x="90" y="104" width="4" height="40" fill="#8e8878"/>${towerWord ? `<text x="80" y="95" text-anchor="middle" font-size="9" font-family="monospace" font-weight="700" fill="#2b2a26">${towerWord}</text>` : ""}`);

  // Courthouse.
  const cx = w / 2;
  parts.push(`<rect x="${cx - 120}" y="110" width="240" height="90" fill="#b9b3a0" stroke="#2b2a26" stroke-width="1.5"/>`);
  parts.push(`<polygon points="${cx - 130},110 ${cx},70 ${cx + 130},110" fill="#c7c1ae" stroke="#2b2a26" stroke-width="1.5"/>`);
  for (let i = 0; i < 6; i++) parts.push(`<rect x="${cx - 100 + i * 40}" y="122" width="10" height="78" fill="#d8d2bf" stroke="#2b2a26" stroke-width="1"/>`);
  parts.push(`<rect x="${cx - 14}" y="160" width="28" height="40" fill="#2b2a26"/>`);
  parts.push(`<circle cx="${cx}" cy="94" r="10" fill="#f7f6ee" stroke="#2b2a26" stroke-width="1"/>`);
  const stopped = f("clock-stopped");
  const hourAngle = stopped ? 120 + 6 : (day * 37) % 360;
  const minAngle = stopped ? 72 : (day * 97) % 360;
  parts.push(`<line x1="${cx}" y1="94" x2="${cx + 5 * Math.sin((hourAngle * Math.PI) / 180)}" y2="${94 - 5 * Math.cos((hourAngle * Math.PI) / 180)}" stroke="#2b2a26" stroke-width="1.5"/><line x1="${cx}" y1="94" x2="${cx + 8 * Math.sin((minAngle * Math.PI) / 180)}" y2="${94 - 8 * Math.cos((minAngle * Math.PI) / 180)}" stroke="#2b2a26" stroke-width="1"/>`);
  parts.push(`<rect x="${cx - 128}" y="200" width="256" height="6" fill="#a39d8a" stroke="#2b2a26" stroke-width="1"/>`);

  // Bandstand on the right.
  const bx = w - 110;
  parts.push(`<polygon points="${bx - 44},150 ${bx},126 ${bx + 44},150" fill="#9a8f78" stroke="#2b2a26" stroke-width="1.5"/>`);
  for (const dx of [-36, -12, 12, 36]) parts.push(`<rect x="${bx + dx - 2}" y="150" width="4" height="48" fill="#2b2a26"/>`);
  parts.push(`<rect x="${bx - 44}" y="196" width="88" height="6" fill="#8a8470" stroke="#2b2a26" stroke-width="1"/>`);
  if (state.cult?.registered) parts.push(`<line x1="${bx}" y1="126" x2="${bx}" y2="100" stroke="#2b2a26" stroke-width="1.5"/><polygon points="${bx},100 ${bx + 22},106 ${bx},112" fill="#7c6fb5"/>`);
  if (f("mirror")) parts.push(`<rect x="${cx + 150}" y="120" width="60" height="70" fill="#eef1f6" stroke="#2b2a26" stroke-width="1.5" transform="rotate(-18 ${cx + 180} 155)"/><text x="${cx + 180}" y="215" text-anchor="middle" font-size="8" font-family="monospace" fill="#2b2a26">THE MIRROR</text>`);
  if (f("monument")) parts.push(`<rect x="${cx - 190}" y="170" width="36" height="30" fill="#8a7a4a" stroke="#2b2a26" stroke-width="1.5"/><rect x="${cx - 186}" y="178" width="28" height="10" fill="#d8c88a" stroke="#2b2a26" stroke-width="0.8"/>`);
  if (f("shrine")) parts.push(`<ellipse cx="90" cy="206" rx="40" ry="8" fill="#1e1c19"/><rect x="48" y="188" width="84" height="3" fill="#2b2a26"/>${[55, 70, 85, 100, 115].map((x) => `<rect x="${x}" y="178" width="2" height="10" fill="#f7f6ee"/><circle cx="${x + 1}" cy="176" r="2" fill="#f2d27a"/>`).join("")}`);
  const ark = state.citizens.find((c) => c.tags.includes("ark-launched") || (c.tags.includes("ark") && day >= 20));
  if (ark && !f("ark-towed")) parts.push(`<path d="M ${w - 250},198 L ${w - 236},214 L ${w - 160},214 L ${w - 150},198 Z" fill="#5a4a30" stroke="#2b2a26" stroke-width="1.5"/><rect x="${w - 226}" y="176" width="60" height="22" fill="#7a6a48" stroke="#2b2a26" stroke-width="1"/><text x="${w - 196}" y="190" text-anchor="middle" font-size="7" font-family="monospace" fill="#f7f6ee">ARK</text>`);
  if (f("bonfire") && lastNight) parts.push(`<polygon points="${cx - 70},200 ${cx - 50},150 ${cx - 40},175 ${cx - 30},140 ${cx - 15},170 ${cx - 5},155 ${cx + 10},200" fill="#d9893a"/><polygon points="${cx - 60},200 ${cx - 40},170 ${cx - 25},185 ${cx - 10},165 ${cx},200" fill="#f2d27a"/>`);

  // The crowd.
  const styles: Array<[CopingStyle, number]> = (["hedonism", "piety", "rage", "hoarding", "duty", "bargaining", "denial", "confession", "flight", "quiet"] as CopingStyle[]).map((s) => [s, frac(s)]);
  styles.sort((a, b) => b[1] - a[1]);
  const total = Math.round(6 + 44 * (1 - frac("quiet") * 2) * Math.min(1, 0.4 + (frac("hedonism") + frac("piety") + frac("rage") + frac("bargaining")) * 1.5));
  const crowd: Array<{ y: number; svg: string }> = [];
  let placed = 0;
  for (const [style, fr] of styles) {
    const n = Math.round(total * fr);
    for (let i = 0; i < n && placed < 60; i++) {
      const k = placed++;
      const x = 40 + hash(k * 3 + day) * (w - 80);
      const depth = hash(k * 7 + day * 3);
      const y = ground + 6 + depth * 36;
      const size = 26 + depth * 14;
      const pose = style === "hedonism" ? (hash(k * 5) > 0.4 ? "arms" : "stand") : style === "piety" ? (hash(k * 5) > 0.5 ? "kneel" : "stand") : style === "rage" ? (hash(k * 5) > 0.5 ? "sign" : "stand") : style === "hoarding" ? "box" : style === "quiet" ? "sit" : style === "bargaining" ? (hash(k * 5) > 0.7 ? "sign" : "stand") : "stand";
      const shade = depth > 0.6 ? "#1e1c19" : "#3a3630";
      crowd.push({ y, svg: figure(x, y, size, pose, shade) });
    }
  }
  const sorted = crowd.sort((a, b) => a.y - b.y).map((c) => c.svg);
  parts.push(`<rect x="0" y="${ground}" width="${w}" height="${h - ground}" fill="#9a9484"/>`);
  if (frac("hedonism") > 0.25) parts.push(`<path d="M 40,120 Q ${w / 2},${150} ${w - 40},118" fill="none" stroke="#2b2a26" stroke-width="1"/>${Array.from({ length: 18 }, (_, i) => { const x = 60 + i * ((w - 120) / 17); const y = 120 + 28 * Math.sin((i / 17) * Math.PI); return `<polygon points="${x - 4},${y} ${x + 4},${y} ${x},${y + 8}" fill="${i % 2 ? "#d9893a" : "#f7f6ee"}"/>`; }).join("")}`);
  parts.push(...sorted);
  if (frac("piety") > 0.15 || f("vigil")) parts.push(Array.from({ length: 12 }, (_, i) => `<circle cx="${80 + i * 52 + hash(i) * 20}" cy="${ground + 20 + hash(i + 9) * 30}" r="1.6" fill="#f2d27a"/>`).join(""));
  if (frac("flight") > 0.06) parts.push(`<rect x="8" y="${ground - 14}" width="46" height="18" rx="4" fill="#2b2a26"/><circle cx="18" cy="${ground + 6}" r="4" fill="#2b2a26"/><circle cx="44" cy="${ground + 6}" r="4" fill="#2b2a26"/>`);

  // Photograph finish: grain and vignette, black and white.
  parts.push(`<rect width="${w}" height="${h}" filter="url(#grain)" opacity="0.28"/>`);
  parts.push(`<rect width="${w}" height="${h}" fill="url(#vignette)"/>`);

  const defs = `<defs>
    <filter id="grain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency="0.8" numOctaves="2" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/></filter>
    <radialGradient id="vignette" cx="50%" cy="50%" r="70%"><stop offset="0.6" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity="0.45"/></radialGradient>
  </defs>`;
  const svg = `<svg viewBox="0 0 ${w} ${h}" width="100%" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="The square, Day ${day}" style="filter:grayscale(1) contrast(1.05)">${defs}${parts.join("")}</svg>`;

  const dom = styles[0]?.[0] ?? "duty";
  const what: Record<CopingStyle, string> = {
    denial: "Business as usual.",
    duty: "People on their way to work.",
    hedonism: "The third night of something.",
    piety: night ? "The vigil, second sitting." : "The vigil, early.",
    rage: "The picket.",
    hoarding: "Residents carrying things home.",
    flight: "Northbound, mostly.",
    confession: "People telling each other things.",
    bargaining: "Signs, facing up.",
    quiet: "Quiet. The paper is printing anyway.",
  };
  const extras: string[] = [];
  if (ark && !f("ark-towed")) extras.push("the vessel, right");
  if (f("bonfire") && lastNight) extras.push("the bonfire");
  if (f("mirror")) extras.push("the mirror");
  if (state.cult?.registered) extras.push("the bandstand, booked");
  const caption = `The square, Day ${day}. ${what[dom]}${extras.length ? ` With ${extras.join(", ")}.` : ""} Photograph: the ${state.paperName}.`;
  return { svg, caption };
}
