// All simulation state is plain JSON: no classes, no Maps, no Dates. A run is reproducible from seed plus actions.

export const COPING_STYLES = [
  "denial",
  "duty",
  "hedonism",
  "piety",
  "rage",
  "hoarding",
  "flight",
  "confession",
  "bargaining",
  "quiet",
] as const;
export type CopingStyle = (typeof COPING_STYLES)[number];

export const DEPT_IDS = ["water", "power", "police", "sanitation", "parks", "records", "pension"] as const;
export type DeptId = (typeof DEPT_IDS)[number];

export type Role = "council" | "chief" | "engineer" | "principal" | "pastor" | "editor" | "actuary";
export type Agenda = "order" | "party" | "legacy";

export interface Traits {
  sociable: number;
  stubborn: number;
  anxious: number;
}

export interface Beliefs {
  real: number;
  miss: number;
  bunker: number;
  federal: number;
}

export interface Citizen {
  id: number;
  first: string;
  last: string;
  age: number;
  street: number;
  job: string;
  dept: DeptId | null;
  homeDept: DeptId | null;
  role: Role | null;
  agenda: Agenda | null;
  coping: CopingStyle;
  copingSince: number;
  prop: Record<CopingStyle, number>;
  traits: Traits;
  mood: number;
  trustOffset: number;
  beliefs: Beliefs;
  present: boolean;
  working: boolean;
  strikeUntil: number;
  tags: string[];
}

export interface Street {
  id: number;
  name: string;
  households: number;
  water: boolean;
  power: boolean;
}

export interface Department {
  id: DeptId;
  name: string;
  required: number;
}

export type DocKind =
  | "permit"
  | "resignation"
  | "complaint"
  | "ordinance"
  | "budget"
  | "federal"
  | "confession"
  | "question"
  | "petition"
  | "memo"
  | "exploit"
  | "staffing";

export interface DocOption {
  id: string;
  label: string;
}

export type Params = Record<string, string | number | boolean>;

export interface Document {
  id: number;
  day: number;
  kind: DocKind;
  template: string;
  sender: number | null;
  senderLabel: string;
  title: string;
  body: string;
  options: DocOption[];
  age: number;
  priority: number;
  payload: Params;
  status: "pending" | "resolved" | "lapsed";
  chosen: string | null;
  resolvedDay: number | null;
  outcome: string | null;
}

export type OrdinanceId =
  | "curfew"
  | "rationing"
  | "priceControls"
  | "closeSchools"
  | "openBars"
  | "optimism"
  | "legalizeAll"
  | "holiday"
  | "payrollFreeze"
  | "raidPension"
  | "welfareChecks"
  | "banHoarding";

export interface Ordinance {
  id: OrdinanceId;
  signedDay: number;
  exploitDay: number;
  exploited: boolean;
  active: boolean;
  by: string;
}

export type ClaimFact = "real" | "miss" | "bunker" | "federal" | "services";

export interface Claim {
  fact: ClaimFact;
  value: boolean;
}

export type Tone = "honest" | "reassuring" | "evasive" | "lie" | "silence";

export interface BulletinOption {
  id: string;
  text: string;
  tone: Tone;
  claim: Claim | null;
}

/** A public statement whose truth the town will eventually test. Bulletins and answers to questions both land here. */
export interface Statement {
  id: string;
  day: number;
  proofDay: number;
  text: string;
  tone: Tone;
  claim: Claim | null;
  source: "bulletin" | "answer" | "order";
  checked: boolean;
  truthful: boolean | null;
}

export interface LedgerEntry {
  day: number;
  text: string;
  names: string[];
  weight: number;
}

export interface PaperItem {
  day: number;
  headline: string;
  body: string;
  weight: number;
}

export interface Kpis {
  permitsProcessed: number;
  permitsApproved: number;
  permitsDenied: number;
  deferrals: number;
  lapsed: number;
  bulletinsIssued: number;
  bulletinsFalse: number;
  ordinancesSigned: number;
  welfareChecks: number;
  headcountStart: number;
}

export interface Office {
  held: boolean;
  lostDay: number | null;
  lostTo: string | null;
}

export interface Cult {
  name: string;
  leaderId: number;
  members: number;
  registered: boolean;
}

export interface Asteroid {
  designation: string;
  name: string;
}

/** A thread about named people that escalates over days and branches on the player's stamps. */
export interface Story {
  id: string;
  params: Params;
  beat: number;
  /** Day the next beat may arrive; 0 while waiting for the current beat to be resolved. */
  nextDay: number;
  choices: string[];
  done: boolean;
}

export type Action =
  | { type: "stamp"; docId: number; option: string }
  | { type: "bulletin"; id: string }
  | { type: "reassign"; citizenId: number; dept: DeptId }
  | { type: "endDay" };

export interface Objective {
  name: string;
  target: string;
  actual: string;
  met: boolean;
}

export interface Epilogue {
  lastEdition: { headline: string; paragraphs: string[] };
  review: { objectives: Objective[]; met: number; verdict: string[] };
  ledger: LedgerEntry[];
}

export interface TownState {
  version: 2;
  seed: number;
  day: number;
  ended: boolean;
  townName: string;
  originalName: string;
  paperName: string;
  population: number;
  asteroid: Asteroid;
  citizens: Citizen[];
  streets: Street[];
  departments: Department[];
  services: Record<DeptId, number>;
  streetPulse: number[][];
  inTray: Document[];
  queued: Document[];
  archive: Document[];
  nextDocId: number;
  stampsPerDay: number;
  stampsLeft: number;
  ordinances: Ordinance[];
  trust: number;
  order: number;
  morale: number;
  treasury: number;
  lowTrustDays: number;
  cult: Cult | null;
  stories: Story[];
  bulletinToday: string | null;
  bulletinOptions: BulletinOption[];
  statements: Statement[];
  ledger: LedgerEntry[];
  paper: PaperItem[];
  events: string[];
  kpis: Kpis;
  office: Office;
  used: Record<string, number>;
  flags: string[];
  budgetWeeks: number;
  budgetWeeksBalanced: number;
  uptimeSum: number;
  rng: number;
  actions: Action[];
  epilogue: Epilogue | null;
}
