define("late.selfResign", {
  maxPerMonth: 1,
  make: () => ({
    kind: "resignation",
    title: "Letter of Resignation: Deputy Clerk",
    body: `I am writing to tender my resignation as Deputy Clerk, effective the thirtieth. I have given this office a month and I would like the last day for myself.\n\nI have not taken the stapler. It is in the top drawer with the stamp.\n\nThis letter is addressed to the Acting Town Manager, who is me, and who will decide.`,
    options: [
      { id: "accept", label: "Accept" },
      { id: "deny", label: "Deny" },
    ],
    sender: null,
    senderLabel: "The Deputy Clerk",
    priority: 8,
  }),
  resolve: (ctx, _doc, option) => {
    const s = ctx.state;
    if (option === "accept") {
      s.flags.push("resigned-self");
      ledger(s, "The Deputy Clerk resigned, effective the thirtieth, and the Acting Town Manager accepted. Both came in on the thirtieth anyway.", [], 4);
      return "Accepted. You will come in tomorrow anyway. You both know that.";
    }
    ledger(s, "The Deputy Clerk's resignation was denied, by the Deputy Clerk, who has noted the date, and the tone.", [], 4);
    return "Denied. You have noted the date, and the tone.";
  },
});

export function senderName(state: Parameters<typeof addr>[0], id: number): string {
  const c = cit(state, id);
  return c ? `${nm(c)} of ${sname(state, c.street)}` : "a resident";
}
