// Procedural office sounds. Nothing is sampled; everything is synthesised on the spot.

let ctx: AudioContext | null = null;
let noiseBuffer: AudioBuffer | null = null;
let humNode: { gain: GainNode; osc: OscillatorNode[] } | null = null;
let muted = false;

function ac(): AudioContext | null {
  try {
    if (!ctx) ctx = new AudioContext();
    if (ctx.state === "suspended") void ctx.resume();
    return ctx;
  } catch {
    return null;
  }
}

function noise(c: AudioContext): AudioBuffer {
  if (noiseBuffer) return noiseBuffer;
  const buf = c.createBuffer(1, c.sampleRate, c.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  noiseBuffer = buf;
  return buf;
}

function burst(c: AudioContext, duration: number, freq: number, q: number, gain: number, type: BiquadFilterType = "bandpass"): void {
  const src = c.createBufferSource();
  src.buffer = noise(c);
  const filter = c.createBiquadFilter();
  filter.type = type;
  filter.frequency.value = freq;
  filter.Q.value = q;
  const g = c.createGain();
  g.gain.setValueAtTime(gain, c.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, c.currentTime + duration);
  src.connect(filter).connect(g).connect(c.destination);
  src.start();
  src.stop(c.currentTime + duration);
}

function thump(c: AudioContext, freq: number, duration: number, gain: number): void {
  const osc = c.createOscillator();
  osc.type = "sine";
  osc.frequency.setValueAtTime(freq, c.currentTime);
  osc.frequency.exponentialRampToValueAtTime(freq * 0.4, c.currentTime + duration);
  const g = c.createGain();
  g.gain.setValueAtTime(gain, c.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, c.currentTime + duration);
  osc.connect(g).connect(c.destination);
  osc.start();
  osc.stop(c.currentTime + duration);
}

/** Rubber stamp on paper on a desk. */
export function stamp(): void {
  if (muted) return;
  const c = ac();
  if (!c) return;
  thump(c, 110, 0.14, 0.5);
  burst(c, 0.06, 1800, 0.8, 0.35);
  burst(c, 0.18, 320, 1.5, 0.2, "lowpass");
}

/** A sheet pulled from the tray. */
export function slide(): void {
  if (muted) return;
  const c = ac();
  if (!c) return;
  burst(c, 0.16, 2600, 0.6, 0.12, "highpass");
}

/** The dot-matrix printer, for the evening edition. */
export function printer(): void {
  if (muted) return;
  const c = ac();
  if (!c) return;
  for (let i = 0; i < 9; i++) {
    setTimeout(() => burst(c, 0.035, 2200 + (i % 3) * 400, 2, 0.14), i * 55);
  }
}

/** The lights, in the quiet. */
export function hum(on: boolean): void {
  const c = ac();
  if (!c) return;
  if (!on || muted) {
    if (humNode) {
      humNode.gain.gain.linearRampToValueAtTime(0, c.currentTime + 0.4);
      const old = humNode;
      setTimeout(() => old.osc.forEach((o) => o.stop()), 500);
      humNode = null;
    }
    return;
  }
  if (humNode) return;
  const g = c.createGain();
  g.gain.setValueAtTime(0, c.currentTime);
  g.gain.linearRampToValueAtTime(0.012, c.currentTime + 1.5);
  const oscs = [60, 120, 180].map((f, i) => {
    const o = c.createOscillator();
    o.type = i === 0 ? "sine" : "triangle";
    o.frequency.value = f;
    const og = c.createGain();
    og.gain.value = i === 0 ? 1 : 0.25 / i;
    o.connect(og).connect(g);
    o.start();
    return o;
  });
  g.connect(c.destination);
  humNode = { gain: g, osc: oscs };
}

export function isMuted(): boolean {
  return muted;
}

export function setMuted(m: boolean): void {
  muted = m;
  if (m) hum(false);
}
