// The town as the planning department would draw it: one square per household, coloured by how they are coping.

import { COPING_STYLES, type CopingStyle, type TownState } from "../sim/types";

export const COPING_COLOR: Record<CopingStyle, string> = {
  denial: "#cbc3ad",
  duty: "#5a7a52",
  hedonism: "#d9893a",
  piety: "#7c6fb5",
  rage: "#b3261e",
  hoarding: "#c2a23c",
  flight: "#7faacb",
  confession: "#a6708f",
  bargaining: "#3f4f85",
  quiet: "#2b2a26",
};

export const COPING_LABEL: Record<CopingStyle, string> = {
  denial: "Carrying on",
  duty: "At work",
  hedonism: "Partying",
  piety: "Praying",
  rage: "Furious",
  hoarding: "Hoarding",
  flight: "Leaving",
  confession: "Confessing",
  bargaining: "Bargaining",
  quiet: "Not answering",
};

function esc(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");
}

export function townMapSvg(state: TownState): string {
  const w = 290;
  const labelW = 92;
  const box = 9;
  const gap = 2;
  const rowH = 22;
  const squareH = 70;
  const legendH = 44;
  const h = squareH + state.streets.length * rowH + legendH + 12;
  const parts: string[] = [];

  // The square.
  const sq = `
  <rect x="0" y="0" width="${w}" height="${squareH}" fill="#e8e2cf"/>
  <rect x="${w / 2 - 44}" y="18" width="88" height="34" fill="#d8d0b8" stroke="#2b2a26" stroke-width="1"/>
  <polygon points="${w / 2 - 48},18 ${w / 2},6 ${w / 2 + 48},18" fill="#d8d0b8" stroke="#2b2a26" stroke-width="1"/>
  ${[0, 1, 2, 3].map((i) => `<rect x="${w / 2 - 36 + i * 22}" y="24" width="4" height="28" fill="#2b2a26" opacity="0.5"/>`).join("")}
  <text x="${w / 2}" y="63" text-anchor="middle" font-size="7" font-family="monospace" fill="#2b2a26" letter-spacing="1">COURTHOUSE SQUARE</text>
  <circle cx="${w - 34}" cy="40" r="11" fill="none" stroke="#2b2a26" stroke-width="1"/>
  <circle cx="${w - 34}" cy="40" r="4" fill="#2b2a26" opacity="0.4"/>
  <text x="${w - 34}" y="63" text-anchor="middle" font-size="6.5" font-family="monospace" fill="#2b2a26">BANDSTAND</text>
  ${state.cult?.registered ? `<line x1="${w - 34}" y1="29" x2="${w - 34}" y2="14" stroke="#2b2a26" stroke-width="1"/><polygon points="${w - 34},14 ${w - 22},18 ${w - 34},22" fill="${COPING_COLOR.piety}"/>` : ""}
  ${state.flags.includes("mirror") ? `<rect x="28" y="22" width="30" height="6" fill="#f7f6ee" stroke="#2b2a26" stroke-width="1" transform="rotate(-20 43 25)"/><text x="43" y="42" text-anchor="middle" font-size="6" font-family="monospace" fill="#2b2a26">MIRROR</text>` : ""}
  ${state.flags.includes("monument") ? `<rect x="70" y="36" width="12" height="12" fill="#c2a23c" stroke="#2b2a26" stroke-width="1"/><text x="76" y="59" text-anchor="middle" font-size="6" font-family="monospace" fill="#2b2a26">CRATE</text>` : ""}
  ${state.flags.includes("shrine") ? `<ellipse cx="22" cy="52" rx="10" ry="5" fill="#2b2a26" opacity="0.6"/><text x="22" y="64" text-anchor="middle" font-size="6" font-family="monospace" fill="#2b2a26">THE PIT</text>` : ""}
  ${state.flags.includes("clock-stopped") ? `<text x="${w / 2}" y="16" text-anchor="middle" font-size="6" font-family="monospace" fill="#b3261e">4:12</text>` : ""}`;
  parts.push(sq);

  // Streets.
  const byStreet = state.streets.map((st) => state.citizens.filter((c) => c.street === st.id));
  state.streets.forEach((st, i) => {
    const y = squareH + 6 + i * rowH;
    const out = !st.water || !st.power;
    parts.push(`<rect x="0" y="${y - 3}" width="${w}" height="${rowH}" fill="${out ? "#dcd6c4" : i % 2 ? "#f3efe4" : "#f8f7ef"}"/>`);
    if (!st.water) parts.push(`<rect x="0" y="${y - 3}" width="3" height="${rowH}" fill="#3f6fa8"/>`);
    if (!st.power) parts.push(`<rect x="3" y="${y - 3}" width="3" height="${rowH}" fill="#2b2a26"/>`);
    parts.push(`<text x="9" y="${y + 9}" font-size="8" font-family="monospace" fill="#2b2a26">${esc(st.name.length > 15 ? st.name.slice(0, 14) + "." : st.name)}</text>`);
    const houses = byStreet[i] ?? [];
    houses.forEach((c, k) => {
      const x = labelW + k * (box + gap);
      if (x + box > w - 2) return;
      const title = `${esc(c.first)} ${esc(c.last)}, ${c.present ? COPING_LABEL[c.coping].toLowerCase() : "left town"}`;
      if (!c.present) {
        parts.push(`<rect x="${x}" y="${y}" width="${box}" height="${box}" fill="none" stroke="#9a9484" stroke-width="1" stroke-dasharray="2 1"><title>${title}</title></rect>`);
        return;
      }
      parts.push(`<rect x="${x}" y="${y}" width="${box}" height="${box}" fill="${COPING_COLOR[c.coping]}" stroke="#2b2a26" stroke-width="0.5"><title>${title}</title></rect>`);
      if (c.tags.includes("ark")) parts.push(`<polygon points="${x + 1},${y - 1} ${x + box - 1},${y - 1} ${x + box / 2},${y - 5}" fill="#3f4f85"/>`);
      if (c.tags.includes("grocer") || c.tags.includes("banker")) parts.push(`<rect x="${x + box - 4}" y="${y - 3}" width="4" height="3" fill="#c2a23c" stroke="#2b2a26" stroke-width="0.5"/>`);
      if (c.tags.includes("cult-leader")) parts.push(`<circle cx="${x + box / 2}" cy="${y - 3}" r="2" fill="#7c6fb5" stroke="#2b2a26" stroke-width="0.5"/>`);
      if (c.tags.includes("mayor")) parts.push(`<rect x="${x}" y="${y - 4}" width="${box}" height="2" fill="#b3261e"/>`);
      if (c.role === "council" || c.role === "chief" || c.role === "engineer" || c.role === "editor" || c.role === "actuary" || c.role === "pastor" || c.role === "principal")
        parts.push(`<rect x="${x + 3}" y="${y + 3}" width="3" height="3" fill="#f7f6ee" opacity="0.9"/>`);
    });
  });

  // Legend.
  const ly = squareH + 10 + state.streets.length * rowH;
  COPING_STYLES.forEach((s, i) => {
    const col = i % 5;
    const row = Math.floor(i / 5);
    const x = 8 + col * 56;
    const y = ly + row * 14;
    parts.push(`<rect x="${x}" y="${y}" width="8" height="8" fill="${COPING_COLOR[s]}" stroke="#2b2a26" stroke-width="0.5"/><text x="${x + 11}" y="${y + 7}" font-size="7" font-family="monospace" fill="#2b2a26">${esc(COPING_LABEL[s])}</text>`);
  });
  parts.push(`<text x="${w - 4}" y="${ly + 36}" text-anchor="end" font-size="6.5" font-family="monospace" fill="#5b584f">bars: water out, power out. dashed: left town</text>`);

  return `<svg viewBox="0 0 ${w} ${h}" width="100%" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Map of the town, Day ${state.day}">${parts.join("")}</svg>`;
}
